// Local pattern classifier, the second line of defense before a domain
// falls into the generic grey bucket. Instead of maintaining an ever-growing
// list of exact domains, this matches structural signals that hold across
// sites nobody's ever added by name: the TLD a business registered under,
// words in the hostname itself, the URL path shape (a checkout flow looks
// like a checkout flow on any storefront), and the tab title. Checked in
// that order, strongest signal first, so a weak title match never
// pre-empts a strong domain-suffix match from a later rule.
//
// Deliberately NOT using cookies or request-trace data for this. Reading
// cookies would need the "cookies" permission plus broad host_permissions
// (effectively <all_urls>), which (a) is real user data leaving the "stored
// locally, works on tab metadata only" model the rest of Stax follows, and
// (b) doesn't even give a better signal, a cookie tells you a site sets
// trackers, not what category it is. URL/title patterns cover the same
// ground without touching page content or expanding what Stax can see.
const PATTERN_RULES = [
  {
    name: "Shopping",
    color: "orange",
    hostSuffixes: [".shop", ".store"],
    hostKeywords: ["shop", "store", "kaufen", "shopping", "boutique", "market", "deals", "outlet"],
    pathPatterns: [/^\/(cart|checkout|basket|panier|warenkorb|carrito|carrello)(\/|$)/i],
    titlePatterns: [/\b(shopping cart|add to cart|warenkorb|panier|zum warenkorb)\b/i]
  },
  {
    name: "Finance & Pay",
    color: "green",
    hostSuffixes: [".bank"],
    hostKeywords: ["bank", "banque", "banca", "finance", "geld", "payment", "invest"],
    pathPatterns: [/^\/(invoice|rechnung|facture|statement|kontoauszug)(\/|$)/i],
    titlePatterns: [/\b(invoice|rechnung|account balance|kontostand)\b/i]
  },
  {
    name: "Travel",
    color: "purple",
    hostSuffixes: [".travel", ".flights"],
    hostKeywords: ["travel", "flight", "flug", "hotel", "reise", "voyage", "airlines"],
    pathPatterns: [/^\/(flight|flug|booking|reservation|itinerary)s?(\/|$)/i],
    titlePatterns: [/\b(boarding pass|check-?in|flight status|booking confirm(ed|ation))\b/i]
  },
  {
    name: "News & Reading",
    color: "cyan",
    hostSuffixes: [".news"],
    hostKeywords: ["news", "nachrichten", "aktuell", "zeitung", "journal", "presse", "actualite", "noticias"],
    pathPatterns: [/^\/(article|story|nachricht|breaking)s?(\/|$)/i],
    titlePatterns: []
  },
  {
    name: "Development",
    color: "blue",
    hostSuffixes: [".dev"],
    hostKeywords: ["docs", "dev", "api", "sdk", "github"],
    pathPatterns: [/^\/[^/]+\/[^/]+\/(pull|issues|commit|blob|tree|compare|releases)(\/|$)/i],
    titlePatterns: [/\b(pull request|merge request|\d+ commits?|compare changes)\b/i]
  }
];

function patternCategoryFor(host, pathname, title) {
  const tokens = host.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
  const path = (pathname || "").toLowerCase();
  const titleLower = (title || "").toLowerCase();

  // Tier 1: TLD/host suffix. Registering under .shop or .bank bakes the
  // category into the domain itself, about as reliable as a signal gets.
  for (const rule of PATTERN_RULES) {
    if (rule.hostSuffixes.some(suf => host.endsWith(suf))) return { name: rule.name, color: rule.color };
  }
  // Tier 2: hostname token match (the old keyword behavior, unchanged).
  for (const rule of PATTERN_RULES) {
    if (rule.hostKeywords.some(kw => tokens.includes(kw))) return { name: rule.name, color: rule.color };
  }
  // Tier 3: URL path shape, a checkout or PR-review URL looks the same
  // structurally on almost any storefront or git host, listed or not.
  for (const rule of PATTERN_RULES) {
    if (rule.pathPatterns.some(p => p.test(path))) return { name: rule.name, color: rule.color };
  }
  // Tier 4: tab title. Weakest signal (titles are the noisiest source), so
  // it only gets checked once nothing structural has matched at all.
  for (const rule of PATTERN_RULES) {
    if (rule.titlePatterns.some(p => p.test(titleLower))) return { name: rule.name, color: rule.color };
  }
  return null;
}

const MIN_TABS_FOR_FALLBACK_GROUP = 2;

// Query params that identify where a link came from, never what it points at.
// Stripping them is what turns "the same article opened from three places"
// into an actual duplicate rather than three distinct URLs.
const TRACKING_PARAMS = [
  "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "utm_id",
  "fbclid", "gclid", "gbraid", "wbraid", "msclkid", "twclid", "igshid", "ttclid",
  "ref", "ref_src", "referrer", "source", "mc_cid", "mc_eid", "yclid", "_ga",
  "spm", "scm", "at_medium", "at_campaign", "s_kwcid", "ck_subscriber_id"
];

// Canonical form for comparison only. Never navigate to this, only compare
// it: two URLs that normalize the same are treated as the same page.
function normalizeUrl(rawUrl) {
  try {
    const u = new URL(rawUrl);
    TRACKING_PARAMS.forEach(p => u.searchParams.delete(p));
    u.hash = "";                                     // #section is the same page
    u.hostname = u.hostname.replace(/^www\./, "");
    u.protocol = "https:";                           // http/https split is not a real difference here
    // Trailing slash only matters on a path, not on the root itself.
    if (u.pathname.length > 1 && u.pathname.endsWith("/")) u.pathname = u.pathname.slice(0, -1);
    u.searchParams.sort();                           // param order should not create a "new" URL
    return u.toString();
  } catch {
    return rawUrl;
  }
}

// Words that appear in page titles everywhere and say nothing about the topic,
// so they should never end up being the name of a group.
const TITLE_STOPWORDS = new Set([
  "the", "a", "an", "and", "or", "of", "for", "to", "in", "on", "with", "your",
  "my", "you", "is", "are", "how", "what", "why", "docs", "documentation",
  "home", "page", "official", "site", "website", "online", "free", "best",
  "guide", "tutorial", "introduction", "intro", "overview", "get", "getting",
  "started", "new", "search", "results", "login", "sign", "up", "welcome"
]);

// Finds a shared label across a cluster of tab titles, so a fallback group
// can be named "React Router" instead of "reactrouter.com". Deliberately
// non-AI: it's instant, free, and works offline.
function commonTitleLabel(titles) {
  const tokenSets = titles
    .map(t => (t || "")
      .toLowerCase()
      .split(/[^\p{L}\p{N}+#.]+/u)
      .filter(w => w.length > 2 && !TITLE_STOPWORDS.has(w)))
    .filter(set => set.length);

  // Two titles is the minimum that can establish a *shared* label; one title
  // would just be that page's name masquerading as a category.
  if (tokenSets.length < 2) return null;

  // Keep only words present in most of the cluster. Requiring all of them is
  // too strict once a stray tab joins the group, so this uses a majority.
  const needed = Math.max(2, Math.ceil(tokenSets.length * 0.6));
  const counts = new Map();
  tokenSets.forEach(set => {
    new Set(set).forEach(w => counts.set(w, (counts.get(w) || 0) + 1));
  });

  const shared = [...counts.entries()]
    .filter(([, n]) => n >= needed)
    .sort((a, b) => b[1] - a[1] || b[0].length - a[0].length)
    .slice(0, 3)
    .map(([w]) => w);

  if (!shared.length) return null;

  // Re-case from the first title that contains the word, so acronyms and
  // product names keep their real capitalisation (API, PostgreSQL, iOS).
  // Words are then re-sorted into the order they actually appear in that
  // title, otherwise ranking by frequency produces "Router React".
  const reference = titles.find(t => shared.every(w => new RegExp(`\\b${w}\\b`, "i").test(t || ""))) || titles[0] || "";

  const label = shared
    .map(word => {
      const safe = word.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      for (const t of titles) {
        const m = (t || "").match(new RegExp(`\\b${safe}\\b`, "i"));
        if (m) return { word: m[0], pos: reference.toLowerCase().indexOf(word) };
      }
      return { word, pos: 9999 };
    })
    .sort((a, b) => (a.pos < 0 ? 9999 : a.pos) - (b.pos < 0 ? 9999 : b.pos))
    .map(x => x.word)
    .join(" ");

  return label.length > 26 ? label.slice(0, 26).trim() : label;
}

// Exact match or proper subdomain only, never a bare substring test.
function hostMatches(host, domain) {
  return host === domain || host.endsWith("." + domain);
}

function isLocalHost(host) {
  return host === "localhost" || host === "127.0.0.1" || host.endsWith(".localhost");
}

async function getAllRules() {
  const { customRules = [] } = await chrome.storage.sync.get(["customRules"]);
  // customRules: [{ domains: ["a.com","b.com"], name: "Work", color: "blue" }, ...]
  // Custom rules are checked first so a user can override a built-in category.
  const normalizedCustom = customRules
    .filter(r => r && r.name && Array.isArray(r.domains) && r.domains.length)
    .map(r => ({ name: r.name, color: r.color || "grey", domains: r.domains }));
  return [...normalizedCustom, ...BUILTIN_CATEGORY_RULES];
}

async function getCategoryForTab(url, rules, title) {
  // chrome-extension:// and moz-extension:// weren't covered by the old regex
  // (it only matched "chrome:", not "chrome-extension:"), so extension pages
  // like the built-in PDF viewer could slip through and get dumped into a
  // grey group named after the extension ID.
  if (!url || /^(chrome|chrome-extension|brave|edge|edge-extension|moz-extension|about|file):/.test(url)) return null;
  let host, pathname;
  try {
    const parsed = new URL(url);
    host = parsed.hostname;
    pathname = parsed.pathname;
  } catch (err) {
    console.warn("Stax: could not parse tab URL", url, err);
    return null;
  }

  if (isLocalHost(host)) {
    return { name: "Development", color: "blue" };
  }

  for (const rule of rules) {
    if (rule.domains.some(d => hostMatches(host, d))) {
      return { name: rule.name, color: rule.color };
    }
  }

  // Second pass: pattern match across TLD, hostname tokens, URL path shape,
  // and tab title, still 100% local/instant, no page content is read.
  const patternHit = patternCategoryFor(host, pathname, title);
  if (patternHit) return patternHit;

  // Last resort: bucket by root domain name, but only if enough tabs share
  // it, handled by the caller (runLocalSort), which knows the full tab list.
  const cleanHost = host.replace(/^www\./, "").split(".")[0];
  if (cleanHost && cleanHost.length > 2) {
    return { name: cleanHost.toUpperCase(), color: "grey", isFallback: true };
  }
  return null;
}

async function safeGroup(tabIds, windowId, title, color) {
  try {
    const groupId = await chrome.tabs.group({ tabIds, createProperties: { windowId } });
    await chrome.tabGroups.update(groupId, { title, color });
    return groupId;
  } catch (err) {
    // A tab can close mid-sort; don't let that kill the whole handler.
    console.warn(`Stax: failed to group "${title}"`, err);
    return null;
  }
}


// ===== modules/sort.js =====

// sort.js: local sort engine, auto-sort scheduler, safeGroup helper.
// Depends on classifier.js being loaded first.


// ---- Quick Actions ----

// Runs the local rule engine and returns both how many groups it made AND
// which tabs it couldn't confidently place, the leftover list is what lets
// hybrid sort hand off to AI instead of just leaving them scattered.
async function runLocalSortCore(windowId) {
  const tabs = await chrome.tabs.query({ windowId, pinned: false });
  const rules = await getAllRules();
  const groupsMap = new Map();
  const groupedTabIds = new Set();

  for (const tab of tabs) {
    const cat = await getCategoryForTab(tab.url, rules, tab.title);
    if (cat) {
      if (!groupsMap.has(cat.name)) {
        groupsMap.set(cat.name, { color: cat.color, tabIds: [], titles: [], isFallback: !!cat.isFallback });
      }
      groupsMap.get(cat.name).tabIds.push(tab.id);
      groupsMap.get(cat.name).titles.push(tab.title || "");
    }
  }

  let groupsCreated = 0;
  const createdGroupIds = [];
  for (const [name, { color, tabIds, titles, isFallback }] of groupsMap) {
    if (tabIds.length === 0) continue;
    if (isFallback && tabIds.length < MIN_TABS_FOR_FALLBACK_GROUP) continue; // no single-tab noise groups

    // Fallback groups are named after a hostname, which is the least useful
    // label available. If the titles in the cluster share a topic, use that
    // instead: "React Router" beats "reactrouter.com". Only fallback groups
    // get renamed, since a real category name is already correct.
    let label = name;
    if (isFallback) {
      const smart = commonTitleLabel(titles);
      if (smart) label = smart;
    }

    const groupId = await safeGroup(tabIds, windowId, label, color);
    if (groupId != null) {
      groupsCreated++;
      createdGroupIds.push(groupId);
      tabIds.forEach(id => groupedTabIds.add(id));
    }
  }

  const leftoverTabs = tabs.filter(t => !groupedTabIds.has(t.id) && !/^(chrome|brave|edge|about):/.test(t.url || ""));
  return { groupsCreated, leftoverTabs, createdGroupIds };
}

async function runLocalSort(windowId) {
  const { groupsCreated, createdGroupIds } = await runLocalSortCore(windowId);
  if (createdGroupIds.length) await recordLastAction({ type: "sort", windowId, groupIds: createdGroupIds });
  return { groupsCreated };
}

// Local rules first, then AI covers whatever's left over, the two engines
// used to be totally disconnected (AI only ever re-sorted everything from
// scratch on a separate button), so tabs the rule engine couldn't place
// just sat there even with a key configured. This is the fix for that.
async function runHybridSort(windowId) {
  const { groupsCreated: localGroups, leftoverTabs, createdGroupIds: localGroupIds } = await runLocalSortCore(windowId);

  const hasKey = await hasApiKeyConfigured();
  let result;
  let allGroupIds = localGroupIds;
  if (!hasKey || leftoverTabs.length < 2) {
    result = { ok: true, groupsCreated: localGroups, aiUsed: false };
  } else {
    const aiResult = await runAiSortOnTabs(windowId, leftoverTabs);
    if (!aiResult.ok) {
      // AI leg failing shouldn't erase the local-sort win, surface it as a
      // partial success rather than an error.
      result = { ok: true, groupsCreated: localGroups, aiUsed: false, aiError: aiResult.error };
    } else {
      allGroupIds = allGroupIds.concat(aiResult.createdGroupIds || []);
      result = { ok: true, groupsCreated: localGroups + aiResult.groupsCreated, aiUsed: true };
    }
  }
  if (allGroupIds.length) await recordLastAction({ type: "sort", windowId, groupIds: allGroupIds });
  return result;
}

async function hasApiKeyConfigured() {
  const { provider = "anthropic", anthropicApiKey, geminiApiKey } =
    await chrome.storage.local.get(["provider", "anthropicApiKey", "geminiApiKey"]);
  return !!(provider === "gemini" ? geminiApiKey : anthropicApiKey);
}

async function ungroupAllTabs(windowId) {
  const tabs = await chrome.tabs.query({ windowId });
  const groupedTabIds = tabs.filter(t => t.groupId !== chrome.tabGroups.TAB_GROUP_ID_NONE).map(t => t.id);
  if (groupedTabIds.length) {
    try {
      await chrome.tabs.ungroup(groupedTabIds);
    } catch (err) {
      console.warn("Stax: ungroupAllTabs failed", err);
    }
  }
}

async function ungroupOne(groupId) {
  try {
    const tabs = await chrome.tabs.query({ groupId });
    const tabIds = tabs.map(t => t.id);
    if (tabIds.length) await chrome.tabs.ungroup(tabIds);
    return true;
  } catch (err) {
    console.warn("Stax: ungroupOne failed", err);
    return false;
  }
}

// Dedupes across ALL windows, matching the README's claim.
// `strict` compares raw URLs (the old behaviour). Default compares normalized
// URLs, which catches the same page opened from different links: tracking
// params stripped, fragment and trailing slash ignored, params sorted.
// The tab kept is always the oldest one, so focus doesn't jump unexpectedly.
async function removeDuplicates({ strict = false } = {}) {
  const tabs = await chrome.tabs.query({ pinned: false });
  const seen = new Set();
  const dups = [];
  const dupRecords = [];
  for (const tab of tabs) {
    if (!tab.url) continue;
    const key = strict ? tab.url : normalizeUrl(tab.url);
    if (seen.has(key)) {
      dups.push(tab.id);
      dupRecords.push({ url: tab.url, title: tab.title || "" });
    } else {
      seen.add(key);
    }
  }
  if (dups.length) {
    try {
      const [activeTab] = await chrome.tabs.query({ active: true, lastFocusedWindow: true });
      await chrome.tabs.remove(dups);
      await recordLastAction({ type: "dedupe", windowId: activeTab?.windowId, removedTabs: dupRecords });
    } catch (err) {
      console.warn("Stax: removeDuplicates failed", err);
    }
  }
  return dups.length;
}


// ===== modules/ai.js =====

// ai.js: AI grouping (Anthropic + Gemini), retry logic, response parsing.
// Depends on sort.js (runAiSortOnTabs calls safeGroup).

// ---- AI Context Grouping ----

// Retries a fetch-returning function on transient overload errors
// (Gemini 503 UNAVAILABLE, Anthropic 529 overloaded) with exponential
// backoff. Anything else (bad key, malformed request) fails immediately,
// no point retrying a 401 or 400.
const RETRYABLE_STATUS = new Set([429, 500, 503, 529]);

async function fetchWithRetry(fn, { retries = 3, baseDelayMs = 800 } = {}) {
  let lastErr;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn();
    } catch (err) {
      lastErr = err;
      const status = err.status;
      const isRetryable = status && RETRYABLE_STATUS.has(status);
      if (!isRetryable || attempt === retries) throw err;
      const delay = baseDelayMs * Math.pow(2, attempt) + Math.random() * 200;
      console.warn(`Stax: AI request got ${status}, retrying in ${Math.round(delay)}ms (attempt ${attempt + 1}/${retries})`);
      await new Promise(r => setTimeout(r, delay));
    }
  }
  throw lastErr;
}

async function callAnthropic(apiKey, tabSummaries) {
  return fetchWithRetry(async () => {
    const res = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": apiKey,
        "anthropic-version": "2023-06-01"
      },
      body: JSON.stringify({
        model: "claude-sonnet-4-6",
        max_tokens: 1024,
        messages: [{ role: "user", content: buildAiPrompt(tabSummaries) }]
      })
    });
    if (!res.ok) {
      const text = await res.text().catch(() => "");
      const err = new Error(`Anthropic API error ${res.status}: ${text.slice(0, 200)}`);
      err.status = res.status;
      throw err;
    }
    const data = await res.json();
    const text = (data.content || []).map(b => b.text || "").join("");
    return parseAiGroups(text);
  });
}

async function callGemini(apiKey, model, tabSummaries) {
  return fetchWithRetry(async () => {
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent?key=${encodeURIComponent(apiKey)}`;
    const res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        contents: [{ parts: [{ text: buildAiPrompt(tabSummaries) }] }]
      })
    });
    if (!res.ok) {
      const text = await res.text().catch(() => "");
      const err = new Error(`Gemini API error ${res.status}: ${text.slice(0, 200)}`);
      err.status = res.status;
      throw err;
    }
    const data = await res.json();
    const text = (data.candidates?.[0]?.content?.parts || []).map(p => p.text || "").join("");
    return parseAiGroups(text);
  });
}

function buildAiPrompt(tabSummaries) {
  return [
    "You are grouping browser tabs into short, meaningful categories based on their title and hostname.",
    "Return ONLY raw JSON (no markdown fences, no prose) matching this shape:",
    '{"groups":[{"name":"Short Group Name","color":"blue","tabIds":[1,2]}]}',
    "Valid colors: grey, blue, red, yellow, green, pink, purple, cyan, orange.",
    "Only include a group if it has 2 or more tabs. Leave unrelated single tabs out entirely.",
    "Tabs:",
    JSON.stringify(tabSummaries)
  ].join("\n");
}

function parseAiGroups(rawText) {
  const cleaned = rawText.replace(/```json|```/g, "").trim();
  const parsed = JSON.parse(cleaned);
  if (!parsed || !Array.isArray(parsed.groups)) throw new Error("Malformed AI response");
  return parsed.groups.filter(g => g && g.name && Array.isArray(g.tabIds) && g.tabIds.length >= 2);
}

// Full AI re-sort: runs on every unpinned tab in the window, ignoring
// whatever the local rules already did. Used by the standalone AI button.
async function runAiSort(windowId) {
  const tabs = await chrome.tabs.query({ windowId, pinned: false });
  const result = await runAiSortOnTabs(windowId, tabs);
  if (result.ok && result.createdGroupIds?.length) {
    await recordLastAction({ type: "sort", windowId, groupIds: result.createdGroupIds });
  }
  return result;
}

// Shared core: groups exactly the tabs it's given. This is what lets hybrid
// sort point AI at only the leftover tabs instead of re-processing everything.
async function runAiSortOnTabs(windowId, tabs) {
  const { provider = "anthropic", anthropicApiKey, geminiApiKey, geminiModel = "gemini-flash-latest" } =
    await chrome.storage.local.get(["provider", "anthropicApiKey", "geminiApiKey", "geminiModel"]);

  const apiKey = provider === "gemini" ? geminiApiKey : anthropicApiKey;
  if (!apiKey) return { ok: false, error: "no-key" };

  if (!tabs.length) return { ok: true, groupsCreated: 0 };

  const tabSummaries = tabs.map(t => {
    let host = "";
    try { host = new URL(t.url).hostname; } catch { /* ignore malformed URL */ }
    return { id: t.id, title: t.title || "", host };
  });

  let groups;
  try {
    groups = provider === "gemini"
      ? await callGemini(apiKey, geminiModel, tabSummaries)
      : await callAnthropic(apiKey, tabSummaries);
  } catch (err) {
    console.warn("Stax: AI sort failed", err);
    return { ok: false, error: err.message || "AI request failed" };
  }

  const validTabIds = new Set(tabs.map(t => t.id));
  let groupsCreated = 0;
  const createdGroupIds = [];
  for (const g of groups) {
    const tabIds = g.tabIds.filter(id => validTabIds.has(id));
    if (tabIds.length < 2) continue;
    const groupId = await safeGroup(tabIds, windowId, g.name, g.color || "grey");
    if (groupId != null) {
      groupsCreated++;
      createdGroupIds.push(groupId);
    }
  }

  return { ok: true, groupsCreated, createdGroupIds };
}

// ---- Message routing ----

chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
  if (msg.type === "LOCAL_SORT") {
    runLocalSort(msg.windowId)
      .then(({ groupsCreated }) => sendResponse({ ok: true, groupsCreated }))
      .catch(err => { console.warn("Stax: LOCAL_SORT failed", err); sendResponse({ ok: false, error: "sort-failed" }); });
    return true;
  }
  if (msg.type === "SMART_SORT") {
    runHybridSort(msg.windowId)
      .then(sendResponse)
      .catch(err => { console.warn("Stax: SMART_SORT failed", err); sendResponse({ ok: false, error: "sort-failed" }); });
    return true;
  }
  if (msg.type === "AI_SORT") {
    runAiSort(msg.windowId)
      .then(sendResponse)
      .catch(err => { console.warn("Stax: AI_SORT failed", err); sendResponse({ ok: false, error: "sort-failed" }); });
    return true;
  }
  if (msg.type === "UNGROUP_ALL") {
    ungroupAllTabs(msg.windowId).then(() => sendResponse({ ok: true }));
    return true;
  }
  if (msg.type === "UNGROUP_ONE") {
    ungroupOne(msg.groupId).then(ok => sendResponse({ ok }));
    return true;
  }
  if (msg.type === "REMOVE_DUPLICATES") {
    removeDuplicates().then(count => sendResponse({ ok: true, removed: count }));
    return true;
  }
});

// Keyboard shortcuts. Chrome only permits four suggested_key bindings per
// extension, so the rest are declared without one: they show up unbound on
// chrome://extensions/shortcuts for the user to assign themselves.
//
// Each one notifies via the badge rather than a popup, because commands fire
// with no UI open and a silent action feels broken.
async function flashBadge(text, colour = "#30d158", ms = 1600) {
  try {
    await chrome.action.setBadgeText({ text });
    await chrome.action.setBadgeBackgroundColor({ color: colour });
    setTimeout(() => refreshBadgeForFocusedWindow(), ms);
  } catch { /* badge is cosmetic */ }
}

chrome.commands.onCommand.addListener(async (command) => {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  const windowId = tab?.windowId;
  if (windowId == null) return;

  try {
    switch (command) {
      case "quick-sort": {
        const res = await runHybridSort(windowId);
        await awardPoints("sort");
        await flashBadge(String(res.groupsCreated ?? 0));
        break;
      }
      case "quick-find": {
        // There's no API to open the popup on a specific view, so stash the
        // intent and let the popup read it on open.
        await chrome.storage.session.set({ stax_open_view: "search" });
        await chrome.action.openPopup().catch(() => {
          // openPopup is not available on every channel; fall back to the
          // side panel, which can be opened programmatically.
          chrome.sidePanel?.open?.({ windowId }).catch(() => {});
        });
        break;
      }
      case "toggle-focus": {
        const state = await getFocusState();
        if (state?.active) {
          await exitFocusMode(windowId);
          await flashBadge("OFF", "#8e8e93");
        } else {
          const res = await enterFocusMode(windowId, { suspendOthers: false });
          await awardPoints("focus");
          await flashBadge("FOCUS", "#7c5cff");
        }
        break;
      }
      case "dedupe-tabs": {
        const removed = await removeDuplicates();
        await awardPoints("dedupe");
        await flashBadge(`-${removed}`, removed ? "#ff9f0a" : "#8e8e93");
        break;
      }
      case "suspend-inactive": {
        const count = await suspendInactiveTabs(windowId);
        await awardPoints("suspend");
        await flashBadge(`z${count}`, "#5aa8e8");
        break;
      }
      case "save-session": {
        const res = await saveSession(windowId, "");
        if (res.ok) await awardPoints("session_save");
        await flashBadge(res.ok ? "SAVED" : "ERR", res.ok ? "#30d158" : "#ff453a");
        break;
      }
      case "archive-stale": {
        const res = await archiveStaleTabs(windowId, 7);
        if (res.ok && res.archived) await awardPoints("archive");
        await flashBadge(res.ok ? `+${res.archived || 0}` : "ERR", "#30d158");
        break;
      }
      case "undo-last": {
        const res = await undoLastAction();
        await flashBadge(res.ok ? "UNDO" : "NONE", res.ok ? "#30d158" : "#8e8e93");
        break;
      }
    }
  } catch (err) {
    console.warn("Stax: command failed", command, err);
    await flashBadge("ERR", "#ff453a");
  }
});

// ---- Auto-sort on new tab ----
// The Preferences toggle previously just wrote a value to storage that
// nothing ever read. This is the actual behavior: deliberately local-rules
// only (never AI), firing an API call on every single new tab would be


// ===== modules/actions.js =====

// actions.js: tab activity tracking, badge, undo, group controls,
// saved sessions, AI search, suspend. No Stacklet logic here.

// slow, costly, and exactly the "relying on AI for something simple"
// problem this is supposed to avoid. Debounced per window so opening a
// batch of tabs at once (restoring a session, opening a link group)
// triggers one sort instead of N overlapping ones.
const autoSortTimers = new Map();
const AUTO_SORT_DEBOUNCE_MS = 900;

async function isAutoSortEnabled() {
  const { autoSortOnNewTab = false } = await chrome.storage.sync.get(["autoSortOnNewTab"]);
  return !!autoSortOnNewTab;
}

function scheduleAutoSort(windowId) {
  if (windowId == null) return;
  clearTimeout(autoSortTimers.get(windowId));
  autoSortTimers.set(windowId, setTimeout(async () => {
    autoSortTimers.delete(windowId);
    if (!(await isAutoSortEnabled())) return;
    try {
      await runLocalSort(windowId);
    } catch (err) {
      console.warn("Stax: auto-sort failed", err);
    }
  }, AUTO_SORT_DEBOUNCE_MS));
}

chrome.tabs.onCreated.addListener((tab) => {
  scheduleAutoSort(tab.windowId);
});

// Also catch the case where a tab's URL only resolves after creation
// (new-tab-page -> typed URL, or a link opened in a blank tab).
chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
  if (changeInfo.status === "complete") {
    scheduleAutoSort(tab.windowId);
  }
});

// ---- Toolbar badge ----
// Shows the unpinned tab count for whichever window currently has focus.
// Recomputed on the events that can change it rather than stored anywhere,
// since a service worker can be killed and restarted between events and
// there's nothing worth persisting here, it's cheap to recalculate.
async function updateBadgeForWindow(windowId) {
  if (windowId == null || windowId === chrome.windows.WINDOW_ID_NONE) return;
  try {
    const tabs = await chrome.tabs.query({ windowId, pinned: false });
    await chrome.action.setBadgeText({ text: tabs.length > 0 ? String(tabs.length) : "" });
    await chrome.action.setBadgeBackgroundColor({ color: "#7c5cff" });
  } catch (err) {
    // Window can close between the event firing and this running, not worth logging.
  }
}

async function refreshBadgeForFocusedWindow() {
  try {
    const win = await chrome.windows.getLastFocused({ windowTypes: ["normal"] });
    await updateBadgeForWindow(win.id);
  } catch (err) {
    await chrome.action.setBadgeText({ text: "" }).catch(() => {});
  }
}

chrome.tabs.onCreated.addListener(() => refreshBadgeForFocusedWindow());
chrome.tabs.onRemoved.addListener(() => refreshBadgeForFocusedWindow());
chrome.tabs.onUpdated.addListener((tabId, changeInfo) => {
  if (changeInfo.status === "complete") refreshBadgeForFocusedWindow();
});
chrome.windows.onFocusChanged.addListener((windowId) => {
  if (windowId !== chrome.windows.WINDOW_ID_NONE) updateBadgeForWindow(windowId);
});
chrome.runtime.onInstalled.addListener(() => refreshBadgeForFocusedWindow());
chrome.runtime.onStartup.addListener(() => refreshBadgeForFocusedWindow());

// ---- Tab activity tracking (for Suspend Inactive Tabs) ----
// Kept in chrome.storage.session rather than a plain in-memory Map, a
// service worker gets killed and restarted constantly in MV3, and a plain
// Map would silently reset every time that happens. storage.session
// survives worker restarts and only clears when the browser itself closes,
// which is exactly the lifetime this needs.
async function touchTabActive(tabId) {
  if (tabId == null) return;
  try {
    const { tabLastActive = {} } = await chrome.storage.session.get(["tabLastActive"]);
    tabLastActive[tabId] = Date.now();
    await chrome.storage.session.set({ tabLastActive });
  } catch (err) {
    console.warn("Stax: touchTabActive failed", err);
  }
}

chrome.tabs.onActivated.addListener(({ tabId }) => touchTabActive(tabId));
chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
  if (changeInfo.status === "complete" && tab.active) touchTabActive(tabId);
});

// Give every tab that already exists a baseline timestamp. Without this,
// tabs open from before install (or from before the last worker restart)
// have no activity record at all, which makes them invisible to the archive
// sweep, since that deliberately skips tabs it knows nothing about.
async function seedTabActivity() {
  try {
    const tabs = await chrome.tabs.query({});
    const { tabLastActive = {} } = await chrome.storage.session.get(["tabLastActive"]);
    const now = Date.now();
    let added = 0;
    for (const t of tabs) {
      if (tabLastActive[t.id] == null) { tabLastActive[t.id] = now; added++; }
    }
    if (added) await chrome.storage.session.set({ tabLastActive });
  } catch (err) {
    console.warn("Stax: seedTabActivity failed", err);
  }
}

chrome.runtime.onInstalled.addListener(() => seedTabActivity());
chrome.runtime.onStartup.addListener(() => seedTabActivity());

// Drop records for closed tabs so the map doesn't grow across a long session.
chrome.tabs.onRemoved.addListener(async (tabId) => {
  try {
    const { tabLastActive = {} } = await chrome.storage.session.get(["tabLastActive"]);
    if (tabLastActive[tabId] != null) {
      delete tabLastActive[tabId];
      await chrome.storage.session.set({ tabLastActive });
    }
  } catch { /* not worth surfacing */ }
});

const SUSPEND_INACTIVE_THRESHOLD_MS = 20 * 60 * 1000; // 20 minutes

// Discards (not closes) unpinned, inactive, non-audible tabs that haven't
// been focused in a while, frees the RAM/CPU they were using without
// losing them; Chrome reloads the page automatically if you click back in.
async function suspendInactiveTabs(windowId) {
  const tabs = await chrome.tabs.query({ windowId, pinned: false, active: false, audible: false, discarded: false });
  let tabLastActive = {};
  try {
    ({ tabLastActive = {} } = await chrome.storage.session.get(["tabLastActive"]));
  } catch (err) {
    console.warn("Stax: could not read tab activity, treating all as inactive", err);
  }
  const now = Date.now();
  let suspended = 0;
  for (const tab of tabs) {
    const lastActive = tabLastActive[tab.id];
    // Never tracked (tab predates this feature, or we lost the record to a
    // service-worker restart) counts as inactive too rather than being skipped.
    const inactiveFor = lastActive ? now - lastActive : Infinity;
    if (inactiveFor >= SUSPEND_INACTIVE_THRESHOLD_MS) {
      try {
        await chrome.tabs.discard(tab.id);
        suspended++;
      } catch (err) {
        console.warn("Stax: failed to discard tab", tab.id, err);
      }
    }
  }
  return suspended;
}

// ---- Group-level actions (used by the side panel's per-group controls) ----

async function toggleGroupCollapse(groupId) {
  try {
    const group = await chrome.tabGroups.get(groupId);
    await chrome.tabGroups.update(groupId, { collapsed: !group.collapsed });
    return true;
  } catch (err) {
    console.warn("Stax: toggleGroupCollapse failed", err);
    return false;
  }
}

async function renameGroup(groupId, newTitle) {
  const title = (newTitle || "").trim();
  if (!title) return false;
  try {
    await chrome.tabGroups.update(groupId, { title });
    return true;
  } catch (err) {
    console.warn("Stax: renameGroup failed", err);
    return false;
  }
}

// Recreates the group's tabs in a brand-new window. Note: this reopens each
// URL rather than truly relocating the tab, so unsaved form input or scroll
// position won't carry over, a real limitation of the tabs API, which has
// no "move an existing tab group between windows" primitive.
async function moveGroupToNewWindow(groupId) {
  try {
    const group = await chrome.tabGroups.get(groupId);
    const tabs = await chrome.tabs.query({ groupId });
    const urls = tabs.map(t => t.url).filter(Boolean);
    if (!urls.length) return false;

    const newWin = await chrome.windows.create({ url: urls[0] });
    const createdIds = [];
    if (newWin.tabs?.[0]?.id != null) createdIds.push(newWin.tabs[0].id);
    for (let i = 1; i < urls.length; i++) {
      const created = await chrome.tabs.create({ windowId: newWin.id, url: urls[i], active: false });
      createdIds.push(created.id);
    }
    if (createdIds.length) {
      const newGroupId = await chrome.tabs.group({ tabIds: createdIds, createProperties: { windowId: newWin.id } });
      await chrome.tabGroups.update(newGroupId, { title: group.title, color: group.color });
    }
    await chrome.tabs.remove(tabs.map(t => t.id));
    return true;
  } catch (err) {
    console.warn("Stax: moveGroupToNewWindow failed", err);
    return false;
  }
}

async function jumpToTab(tabId) {
  try {
    const tab = await chrome.tabs.update(tabId, { active: true });
    if (tab?.windowId != null) await chrome.windows.update(tab.windowId, { focused: true });
    return true;
  } catch (err) {
    console.warn("Stax: jumpToTab failed", err);
    return false;
  }
}

// ---- Undo ----
// Best-effort, one-step undo for the two actions that can otherwise surprise
// you: a sort that grouped something wrong, and a dedupe that closed a tab
// you actually wanted. Stored in storage.session (survives worker restarts,
// clears on browser close) with a short expiry so "undo" never reaches back
// further than the person would expect.
const LAST_ACTION_KEY = "stax_last_action";
const UNDO_WINDOW_MS = 2 * 60 * 1000; // 2 minutes

async function recordLastAction(action) {
  try {
    await chrome.storage.session.set({ [LAST_ACTION_KEY]: { ...action, timestamp: Date.now() } });
  } catch (err) {
    console.warn("Stax: recordLastAction failed", err);
  }
}

async function getUndoableAction() {
  try {
    const { [LAST_ACTION_KEY]: action } = await chrome.storage.session.get([LAST_ACTION_KEY]);
    if (!action) return null;
    if (Date.now() - action.timestamp > UNDO_WINDOW_MS) return null;
    return action;
  } catch (err) {
    return null;
  }
}

async function clearLastAction() {
  try {
    await chrome.storage.session.remove([LAST_ACTION_KEY]);
  } catch (err) { /* not worth surfacing */ }
}

async function undoLastAction() {
  const action = await getUndoableAction();
  if (!action) return { ok: false, error: "nothing-to-undo" };
  await clearLastAction();

  if (action.type === "sort") {
    for (const groupId of action.groupIds) {
      try {
        const tabs = await chrome.tabs.query({ groupId });
        if (tabs.length) await chrome.tabs.ungroup(tabs.map(t => t.id));
      } catch (err) {
        // Group may already be gone (manually ungrouped since), nothing to undo there.
      }
    }
    return { ok: true, type: "sort" };
  }

  if (action.type === "dedupe") {
    for (const t of action.removedTabs) {
      try {
        await chrome.tabs.create({ windowId: action.windowId, url: t.url, active: false });
      } catch (err) {
        console.warn("Stax: failed to reopen tab during undo", err);
      }
    }
    return { ok: true, type: "dedupe" };
  }

  return { ok: false, error: "unknown-action" };
}

// ---- Saved sessions ----
// A session is a named snapshot of a window's tabs (URL, title, and which
// group each tab was in) so it can be closed now and reopened later, even
// after a full browser restart. Stored in storage.local since a big
// tab list can exceed storage.sync's per-item quota.
const SESSIONS_KEY = "stax_sessions";

async function saveSession(windowId, name) {
  const tabs = await chrome.tabs.query({ windowId, pinned: false });
  const groups = await chrome.tabGroups.query({ windowId });
  const groupById = new Map(groups.map(g => [g.id, g]));

  const tabRecords = tabs
    .filter(t => t.url && !/^(chrome|chrome-extension|brave|edge|edge-extension|moz-extension|about|file):/.test(t.url))
    .map(t => {
      const g = t.groupId !== chrome.tabGroups.TAB_GROUP_ID_NONE ? groupById.get(t.groupId) : null;
      return { url: t.url, title: t.title || "", groupTitle: g?.title || null, groupColor: g?.color || null };
    });
  if (!tabRecords.length) return { ok: false, error: "no-tabs" };

  try {
    const { [SESSIONS_KEY]: sessions = [] } = await chrome.storage.local.get([SESSIONS_KEY]);
    const session = { id: `${Date.now()}`, name: (name || "").trim() || `Session ${sessions.length + 1}`, savedAt: Date.now(), tabs: tabRecords };
    sessions.push(session);
    await chrome.storage.local.set({ [SESSIONS_KEY]: sessions });
    return { ok: true, session: { id: session.id, name: session.name, savedAt: session.savedAt, tabCount: tabRecords.length } };
  } catch (err) {
    console.warn("Stax: saveSession failed", err);
    return { ok: false, error: "storage-failed" };
  }
}

async function listSessions() {
  const { [SESSIONS_KEY]: sessions = [] } = await chrome.storage.local.get([SESSIONS_KEY]);
  // Newest first; don't ship the full tab list to the popup just to render a row.
  return sessions
    .slice()
    .sort((a, b) => b.savedAt - a.savedAt)
    .map(s => ({ id: s.id, name: s.name, savedAt: s.savedAt, tabCount: s.tabs.length }));
}

async function deleteSession(id) {
  const { [SESSIONS_KEY]: sessions = [] } = await chrome.storage.local.get([SESSIONS_KEY]);
  await chrome.storage.local.set({ [SESSIONS_KEY]: sessions.filter(s => s.id !== id) });
  return true;
}

async function restoreSession(id) {
  const { [SESSIONS_KEY]: sessions = [] } = await chrome.storage.local.get([SESSIONS_KEY]);
  const session = sessions.find(s => s.id === id);
  if (!session || !session.tabs.length) return { ok: false, error: "not-found" };

  const [first, ...rest] = session.tabs;
  const newWin = await chrome.windows.create({ url: first.url });
  const firstTabId = newWin.tabs?.[0]?.id;

  // Groups have to be created after every tab exists, since chrome.tabs.group
  // needs real tab ids, collect them per groupTitle as tabs get created.
  const byGroup = new Map();
  if (first.groupTitle) byGroup.set(first.groupTitle, { color: first.groupColor || "grey", tabIds: firstTabId != null ? [firstTabId] : [] });

  for (const t of rest) {
    const created = await chrome.tabs.create({ windowId: newWin.id, url: t.url, active: false });
    if (t.groupTitle) {
      if (!byGroup.has(t.groupTitle)) byGroup.set(t.groupTitle, { color: t.groupColor || "grey", tabIds: [] });
      byGroup.get(t.groupTitle).tabIds.push(created.id);
    }
  }

  for (const [title, { color, tabIds }] of byGroup) {
    if (tabIds.length) await safeGroup(tabIds, newWin.id, title, color);
  }

  return { ok: true };
}

// ---- AI tab search ----
// Same provider/key plumbing as AI grouping, but the prompt asks for a
// single best-match tab id instead of a set of groups, for "find the tab
// where I was booking flights" style natural-language lookups.
function buildSearchPrompt(tabSummaries, query) {
  return [
    "You are helping find one specific browser tab matching a natural-language description.",
    "Return ONLY raw JSON (no markdown fences, no prose) matching this shape:",
    '{"tabId": 123}',
    'If nothing matches reasonably well, return {"tabId": null}.',
    `User is looking for: "${query}"`,
    "Tabs:",
    JSON.stringify(tabSummaries)
  ].join("\n");
}

function parseAiSearchResult(rawText) {
  const cleaned = rawText.replace(/```json|```/g, "").trim();
  const parsed = JSON.parse(cleaned);
  if (!parsed || typeof parsed !== "object") throw new Error("Malformed AI response");
  return parsed.tabId ?? null;
}

async function callAnthropicSearch(apiKey, tabSummaries, query) {
  return fetchWithRetry(async () => {
    const res = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-api-key": apiKey, "anthropic-version": "2023-06-01" },
      body: JSON.stringify({ model: "claude-sonnet-4-6", max_tokens: 256, messages: [{ role: "user", content: buildSearchPrompt(tabSummaries, query) }] })
    });
    if (!res.ok) {
      const text = await res.text().catch(() => "");
      const err = new Error(`Anthropic API error ${res.status}: ${text.slice(0, 200)}`);
      err.status = res.status;
      throw err;
    }
    const data = await res.json();
    const text = (data.content || []).map(b => b.text || "").join("");
    return parseAiSearchResult(text);
  });
}

async function callGeminiSearch(apiKey, model, tabSummaries, query) {
  return fetchWithRetry(async () => {
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent?key=${encodeURIComponent(apiKey)}`;
    const res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ contents: [{ parts: [{ text: buildSearchPrompt(tabSummaries, query) }] }] })
    });
    if (!res.ok) {
      const text = await res.text().catch(() => "");
      const err = new Error(`Gemini API error ${res.status}: ${text.slice(0, 200)}`);
      err.status = res.status;
      throw err;
    }
    const data = await res.json();
    const text = (data.candidates?.[0]?.content?.parts || []).map(p => p.text || "").join("");
    return parseAiSearchResult(text);
  });
}

async function aiSearchTabs(windowId, query) {
  const { provider = "anthropic", anthropicApiKey, geminiApiKey, geminiModel = "gemini-flash-latest" } =
    await chrome.storage.local.get(["provider", "anthropicApiKey", "geminiApiKey", "geminiModel"]);
  const apiKey = provider === "gemini" ? geminiApiKey : anthropicApiKey;
  if (!apiKey) return { ok: false, error: "no-key" };

  const tabs = await chrome.tabs.query({ windowId, pinned: false });
  if (!tabs.length) return { ok: false, error: "no-tabs" };

  const tabSummaries = tabs.map(t => {
    let host = "";
    try { host = new URL(t.url).hostname; } catch { /* ignore malformed URL */ }
    return { id: t.id, title: t.title || "", host };
  });

  try {
    const tabId = provider === "gemini"
      ? await callGeminiSearch(apiKey, geminiModel, tabSummaries, query)
      : await callAnthropicSearch(apiKey, tabSummaries, query);
    return { ok: true, tabId };
  } catch (err) {
    console.warn("Stax: AI search failed", err);
    return { ok: false, error: err.message || "AI search failed" };
  }
}


// ---- Recently closed ----
// Chrome's sessions API gives us a richer recently-closed list than anything
// we could maintain ourselves -- it survives service-worker restarts and
// captures tabs closed by the user directly (not just through Stax).
// We cap at 25 entries and return only the fields the UI needs.
async function getRecentlyClosed(maxResults = 25) {
  try {
    const sessions = await chrome.sessions.getRecentlyClosed({ maxResults });
    return sessions
      .filter(s => s.tab)
      .map(s => ({
        sessionId: s.tab.sessionId,
        title: s.tab.title || "",
        url: s.tab.url || "",
        favIconUrl: s.tab.favIconUrl || "",
        lastModified: s.lastModified
      }));
  } catch (err) {
    console.warn("Stax: getRecentlyClosed failed", err);
    return [];
  }
}

async function restoreRecentlyClosed(sessionId) {
  try {
    await chrome.sessions.restore(sessionId);
    return { ok: true };
  } catch (err) {
    console.warn("Stax: restoreRecentlyClosed failed", err);
    return { ok: false, error: err.message };
  }
}

// ---- Merge / split windows ----

async function mergeAllWindows() {
  const windows = await chrome.windows.getAll({ populate: true, windowTypes: ["normal"] });
  if (windows.length < 2) return { ok: true, merged: 0 };

  // Sort by tab count descending so the biggest window is the target,
  // which keeps its tab order most intact.
  windows.sort((a, b) => b.tabs.length - a.tabs.length);
  const [target, ...sources] = windows;

  let merged = 0;
  for (const win of sources) {
    for (const tab of win.tabs) {
      try {
        await chrome.tabs.move(tab.id, { windowId: target.id, index: -1 });
        merged++;
      } catch (err) {
        console.warn("Stax: merge failed for tab", tab.id, err);
      }
    }
  }
  return { ok: true, merged, targetWindowId: target.id };
}

// Moves each tab group and its tabs into a new window. Ungrouped tabs stay
// in the original window.
async function splitIntoWindows(windowId) {
  const groups = await chrome.tabGroups.query({ windowId });
  if (!groups.length) return { ok: false, error: "no-groups" };

  let created = 0;
  for (const g of groups) {
    const tabs = await chrome.tabs.query({ groupId: g.id });
    if (!tabs.length) continue;
    try {
      const newWin = await chrome.windows.create({ tabId: tabs[0].id });
      const newTabIds = [newWin.tabs[0].id];
      for (let i = 1; i < tabs.length; i++) {
        await chrome.tabs.move(tabs[i].id, { windowId: newWin.id, index: -1 });
        newTabIds.push(tabs[i].id);
      }
      const newGroupId = await chrome.tabs.group({ tabIds: newTabIds, createProperties: { windowId: newWin.id } });
      await chrome.tabGroups.update(newGroupId, { title: g.title, color: g.color });
      created++;
    } catch (err) {
      console.warn("Stax: split failed for group", g.id, err);
    }
  }
  return { ok: true, created };
}

// ---- Group-level extras ----

// Closes every tab in a group. Snapshots them first so Undo can restore,
// since this is the most destructive single click in the UI.
async function closeGroupTabs(groupId) {
  try {
    const tabs = await chrome.tabs.query({ groupId });
    if (!tabs.length) return { ok: false, error: "empty-group" };
    const records = tabs.map(t => ({ url: t.url, title: t.title || "" }));
    const windowId = tabs[0].windowId;
    await chrome.tabs.remove(tabs.map(t => t.id));
    await recordLastAction({ type: "dedupe", windowId, removedTabs: records });
    return { ok: true, closed: records.length };
  } catch (err) {
    console.warn("Stax: closeGroupTabs failed", err);
    return { ok: false, error: err.message };
  }
}

// Moves a group left or right among its siblings. tabGroups.move takes an
// absolute tab index, so we work out the destination from the neighbouring
// group's span rather than trying to offset by a fixed amount.
async function moveGroupBy(groupId, direction) {
  try {
    const group = await chrome.tabGroups.get(groupId);
    const groups = await chrome.tabGroups.query({ windowId: group.windowId });
    const allTabs = await chrome.tabs.query({ windowId: group.windowId });

    // Order groups by the index of their first tab.
    const withIndex = groups.map(g => {
      const tabs = allTabs.filter(t => t.groupId === g.id);
      return { id: g.id, first: Math.min(...tabs.map(t => t.index)), size: tabs.length };
    }).sort((a, b) => a.first - b.first);

    const pos = withIndex.findIndex(g => g.id === groupId);
    const swapWith = withIndex[pos + direction];
    if (pos === -1 || !swapWith) return { ok: false, error: "at-edge" };

    // Moving right: land after the neighbour's last tab. Moving left: land
    // at the neighbour's first tab.
    const target = direction > 0
      ? swapWith.first + swapWith.size - withIndex[pos].size
      : swapWith.first;

    await chrome.tabGroups.move(groupId, { index: Math.max(0, target) });
    return { ok: true };
  } catch (err) {
    console.warn("Stax: moveGroupBy failed", err);
    return { ok: false, error: err.message };
  }
}

// ---- Tab tree ----
// Chrome records which tab opened which via openerTabId. Nothing surfaces
// that, so a research session looks like a flat wall of tabs when it was
// actually a branching trail. This reconstructs the forest.
async function getTabTree(windowId) {
  try {
    const tabs = await chrome.tabs.query({ windowId });
    const byId = new Map(tabs.map(t => [t.id, t]));

    const node = (t) => {
      let host = "";
      try { host = new URL(t.url).hostname.replace(/^www\./, ""); } catch {}
      return { id: t.id, title: (t.title || host || "Untitled").slice(0, 90), host, children: [] };
    };

    const nodes = new Map(tabs.map(t => [t.id, node(t)]));
    const roots = [];

    for (const t of tabs) {
      // A tab counts as a child only if its opener is still open in this
      // window. Orphans (opener closed) become roots rather than vanishing.
      const parent = t.openerTabId != null && byId.has(t.openerTabId)
        ? nodes.get(t.openerTabId)
        : null;
      if (parent) parent.children.push(nodes.get(t.id));
      else roots.push(nodes.get(t.id));
    }

    // Depth is capped when rendering, but compute the real one so the UI can
    // show "+3 deeper" rather than silently truncating.
    const depthOf = (n) => n.children.length ? 1 + Math.max(...n.children.map(depthOf)) : 1;
    const maxDepth = roots.length ? Math.max(...roots.map(depthOf)) : 0;
    const branching = roots.filter(r => r.children.length > 0).length;

    return { ok: true, roots, maxDepth, branching, total: tabs.length };
  } catch (err) {
    console.warn("Stax: getTabTree failed", err);
    return { ok: false, error: err.message };
  }
}


// ===== modules/stacklet.js =====

// stacklet.js: Stacklet companion chat, action execution, allowlist.
// Depends on sort.js and actions.js.

// ---- Stacklet: the AI companion ----
// Same provider/key plumbing as grouping and search. Stacklet gets tab
// titles, hostnames, and current group membership, never page content,
// which would need scripting + <all_urls> and put real browsing data in a
// prompt. It replies in prose and may propose actions, but proposing is all
// it can do on its own: every action comes back to the UI as a confirm card
// unless the user has explicitly switched on auto-run.

const STACKLET_PROFILE_HINTS = {
  developer: "They mostly do software development. Notice things like docs left open across a task, a PR mid-review, or a stale localhost tab.",
  marketing: "They mostly do marketing. Notice campaign research, analytics dashboards, competitor pages, and draft/scheduling tools.",
  research: "They mostly research or study. Notice sources gathered for one topic, papers, and reference material worth grouping together.",
  design: "They mostly do design work. Notice inspiration boards, asset libraries, prototypes, and design tools.",
  general: "They use the browser for a mix of work and personal things."
};

// The only actions Stacklet is allowed to name. Anything outside this list
// is dropped before it ever reaches the UI, so a bad or adversarial model
// response can't invent a capability the extension doesn't intend to expose.
const ALLOWED_STACKLET_ACTIONS = new Set([
  "group_tabs", "close_tabs", "suspend_tabs", "rename_group", "save_session", "smart_sort", "dedupe", "open_tabs"
]);

// Hard ceiling on how many tabs one suggestion can open. Without it a single
// misread request ("open everything about X") could spawn dozens of tabs.
const MAX_TABS_PER_OPEN = 8;

// Only ever open real web pages. Blocks javascript:, data:, file: and
// chrome:// URLs, none of which should come out of a model response and all
// of which are worth refusing explicitly rather than relying on the prompt.
function isSafeOpenUrl(url) {
  try {
    const u = new URL(url);
    return u.protocol === "https:" || u.protocol === "http:";
  } catch {
    return false;
  }
}

function buildStackletPrompt(tabs, groups, profile, history, userMessage) {
  const hint = STACKLET_PROFILE_HINTS[profile] || STACKLET_PROFILE_HINTS.general;
  return [
    "You are Stacklet, a concise, friendly assistant living inside a browser-tab manager called Stax.",
    `About this user: ${hint}`,
    "You can see the user's open tabs (title + hostname + group) and nothing else. You cannot read page content.",
    "",
    "Return ONLY raw JSON (no markdown fences, no prose outside the JSON) in this shape:",
    '{"reply":"a short friendly message, 1-3 sentences","actions":[{"type":"group_tabs","label":"Group 5 research tabs","tabIds":[1,2],"name":"Research","color":"cyan"}]}',
    "",
    "Action types you may use (omit 'actions' entirely if none make sense):",
    '- group_tabs: needs tabIds (2+), name, color. Colors: grey, blue, red, yellow, green, pink, purple, cyan, orange.',
    '- close_tabs: needs tabIds. Only for clear duplicates or obvious junk.',
    '- suspend_tabs: needs tabIds. Frees memory for tabs they are not using.',
    '- rename_group: needs groupId and title.',
    '- save_session: needs name.',
    '- smart_sort: no extra fields. Sorts everything with the local rule engine.',
    '- dedupe: no extra fields. Closes duplicate URLs.',
    '- open_tabs: needs urls (an array of full https:// URLs) and optionally groupName and color.',
    '    Use this to actually open useful material: documentation, references, search results,',
    '    papers, dashboards. Prefer well-known canonical URLs you are confident exist',
    '    (official docs, Wikipedia, MDN, GitHub repos, a search URL). Never invent deep links',
    '    to specific article slugs you are not sure about, since a wrong guess opens a 404.',
    `    Never more than ${MAX_TABS_PER_OPEN} URLs in one action.`,
    "",
    "Every action needs a short human 'label' explaining what it does. Never propose more than 3 actions.",
    "Be genuinely useful and specific about what you actually see. Do not invent tabs that are not listed.",
    "If the user asks you to find, research, or pull up material, use open_tabs rather than telling them you cannot open tabs.",
    "",
    `Open tabs: ${JSON.stringify(tabs)}`,
    `Existing groups: ${JSON.stringify(groups)}`,
    history.length ? `Recent conversation: ${JSON.stringify(history.slice(-6))}` : "",
    `User says: "${userMessage}"`
  ].filter(Boolean).join("\n");
}

function parseStackletReply(rawText) {
  const cleaned = rawText.replace(/```json|```/g, "").trim();
  const parsed = JSON.parse(cleaned);
  if (!parsed || typeof parsed.reply !== "string") throw new Error("Malformed Stacklet response");
  const actions = Array.isArray(parsed.actions) ? parsed.actions : [];
  return {
    reply: parsed.reply,
    actions: actions
      .filter(a => a && ALLOWED_STACKLET_ACTIONS.has(a.type) && typeof a.label === "string")
      .slice(0, 3)
  };
}

async function callStackletProvider(promptText) {
  const { provider = "anthropic", anthropicApiKey, geminiApiKey, geminiModel = "gemini-flash-latest" } =
    await chrome.storage.local.get(["provider", "anthropicApiKey", "geminiApiKey", "geminiModel"]);
  const apiKey = provider === "gemini" ? geminiApiKey : anthropicApiKey;
  if (!apiKey) return { ok: false, error: "no-key" };

  try {
    const raw = await fetchWithRetry(async () => {
      if (provider === "gemini") {
        const url = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(geminiModel)}:generateContent?key=${encodeURIComponent(apiKey)}`;
        const res = await fetch(url, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ contents: [{ parts: [{ text: promptText }] }] })
        });
        if (!res.ok) {
          const text = await res.text().catch(() => "");
          const err = new Error(`Gemini API error ${res.status}: ${text.slice(0, 200)}`);
          err.status = res.status;
          throw err;
        }
        const data = await res.json();
        return (data.candidates?.[0]?.content?.parts || []).map(p => p.text || "").join("");
      }
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json", "x-api-key": apiKey, "anthropic-version": "2023-06-01" },
        body: JSON.stringify({ model: "claude-sonnet-4-6", max_tokens: 1024, messages: [{ role: "user", content: promptText }] })
      });
      if (!res.ok) {
        const text = await res.text().catch(() => "");
        const err = new Error(`Anthropic API error ${res.status}: ${text.slice(0, 200)}`);
        err.status = res.status;
        throw err;
      }
      const data = await res.json();
      return (data.content || []).map(b => b.text || "").join("");
    });
    return { ok: true, raw };
  } catch (err) {
    console.warn("Stax: Stacklet request failed", err);
    return { ok: false, error: err.message || "Stacklet request failed" };
  }
}

async function stackletChat(windowId, userMessage, history = []) {
  const { stackletProfile = "general" } = await chrome.storage.sync.get(["stackletProfile"]);

  const rawTabs = await chrome.tabs.query({ windowId, pinned: false });
  const groups = await chrome.tabGroups.query({ windowId });
  const tabs = rawTabs
    .filter(t => t.url && !/^(chrome|chrome-extension|brave|edge|edge-extension|moz-extension|about|file):/.test(t.url))
    .map(t => {
      let host = "";
      try { host = new URL(t.url).hostname; } catch { /* ignore malformed URL */ }
      return {
        id: t.id,
        title: (t.title || "").slice(0, 120),
        host,
        groupId: t.groupId !== chrome.tabGroups.TAB_GROUP_ID_NONE ? t.groupId : null
      };
    });

  const groupSummaries = groups.map(g => ({ id: g.id, title: g.title || "", color: g.color }));
  const prompt = buildStackletPrompt(tabs, groupSummaries, stackletProfile, history, userMessage);

  const res = await callStackletProvider(prompt);
  if (!res.ok) return res;

  try {
    const { reply, actions } = parseStackletReply(res.raw);
    const { stackletAutoRun = false } = await chrome.storage.sync.get(["stackletAutoRun"]);
    return { ok: true, reply, actions, autoRun: !!stackletAutoRun };
  } catch (err) {
    console.warn("Stax: could not parse Stacklet reply", err);
    return { ok: false, error: "bad-response" };
  }
}

// Executes a single approved action. Every branch re-validates its inputs
// against live tabs rather than trusting ids from the model response,
// tabs close, groups disappear, and a stale id should fail cleanly instead
// of hitting an unrelated tab that happens to have reused the number.
async function runStackletAction(action, windowId) {
  if (!action || !ALLOWED_STACKLET_ACTIONS.has(action.type)) return { ok: false, error: "not-allowed" };

  try {
    if (action.type === "smart_sort") {
      const res = await runHybridSort(windowId);
      return { ok: true, detail: `Created ${res.groupsCreated} group(s).` };
    }

    if (action.type === "dedupe") {
      const removed = await removeDuplicates();
      return { ok: true, detail: `Closed ${removed} duplicate tab(s).` };
    }

    if (action.type === "save_session") {
      const res = await saveSession(windowId, action.name || "Stacklet session");
      return res.ok ? { ok: true, detail: `Saved "${res.session.name}".` } : { ok: false, error: res.error };
    }

    if (action.type === "rename_group") {
      const ok = await renameGroup(action.groupId, action.title);
      return ok ? { ok: true, detail: `Renamed to "${action.title}".` } : { ok: false, error: "rename-failed" };
    }

    if (action.type === "open_tabs") {
      // Validated here rather than trusted from the response: bad protocols
      // are dropped, duplicates collapsed, and the count capped.
      const urls = [...new Set((action.urls || []).filter(isSafeOpenUrl))].slice(0, MAX_TABS_PER_OPEN);
      if (!urls.length) return { ok: false, error: "no-valid-urls" };

      const createdIds = [];
      for (const url of urls) {
        try {
          const tab = await chrome.tabs.create({ windowId, url, active: false });
          createdIds.push(tab.id);
        } catch (err) {
          console.warn("Stax: failed to open", url, err);
        }
      }
      if (!createdIds.length) return { ok: false, error: "open-failed" };

      // Group them on the way in if a name was given, so a research batch
      // doesn't just scatter across the tab strip.
      if (action.groupName && createdIds.length >= 2) {
        const groupId = await safeGroup(createdIds, windowId, action.groupName, action.color || "cyan");
        if (groupId != null) await recordLastAction({ type: "sort", windowId, groupIds: [groupId] });
      }
      return { ok: true, detail: `Opened ${createdIds.length} tab(s).` };
    }

    const liveTabs = await chrome.tabs.query({ windowId });
    const liveIds = new Set(liveTabs.map(t => t.id));
    const tabIds = (action.tabIds || []).filter(id => liveIds.has(id));
    if (!tabIds.length) return { ok: false, error: "no-valid-tabs" };

    if (action.type === "group_tabs") {
      if (tabIds.length < 2) return { ok: false, error: "need-two-tabs" };
      const groupId = await safeGroup(tabIds, windowId, action.name || "Stacklet", action.color || "grey");
      if (groupId == null) return { ok: false, error: "group-failed" };
      await recordLastAction({ type: "sort", windowId, groupIds: [groupId] });
      return { ok: true, detail: `Grouped ${tabIds.length} tab(s).` };
    }

    if (action.type === "suspend_tabs") {
      let count = 0;
      for (const id of tabIds) {
        try { await chrome.tabs.discard(id); count++; } catch (err) { /* tab may be active/audible */ }
      }
      return { ok: true, detail: `Suspended ${count} tab(s).` };
    }

    if (action.type === "close_tabs") {
      // Snapshot before closing so Undo can put them back, this is the one
      // action that destroys something the user can't otherwise recover.
      const records = liveTabs.filter(t => tabIds.includes(t.id)).map(t => ({ url: t.url, title: t.title || "" }));
      await chrome.tabs.remove(tabIds);
      await recordLastAction({ type: "dedupe", windowId, removedTabs: records });
      return { ok: true, detail: `Closed ${tabIds.length} tab(s).` };
    }

    return { ok: false, error: "not-allowed" };
  } catch (err) {
    console.warn("Stax: Stacklet action failed", err);
    return { ok: false, error: err.message || "action-failed" };
  }
}


// ---- Chat history persistence ----
// Conversations used to live only as long as the popup was open, which meant
// closing it lost everything Stacklet had told you and every action you'd
// approved. Persisted here instead.
//
// This does mean writing what you work on to disk, so it's bounded on both
// axes: a hard message cap, and an age cutoff. Plus a clear command, because
// "delete my history" should never require uninstalling.
const CHAT_KEY = "stax_chat_history";
const CHAT_MAX_MESSAGES = 60;
const CHAT_MAX_AGE_DAYS = 30;

async function loadChatHistory() {
  try {
    const { [CHAT_KEY]: raw = [] } = await chrome.storage.local.get([CHAT_KEY]);
    const cutoff = Date.now() - CHAT_MAX_AGE_DAYS * 86400000;
    const fresh = raw.filter(m => (m.at || 0) >= cutoff);
    // Prune on read rather than with a scheduled job: it costs nothing here
    // and there's no worker lifetime to depend on.
    if (fresh.length !== raw.length) {
      await chrome.storage.local.set({ [CHAT_KEY]: fresh });
    }
    return { ok: true, messages: fresh };
  } catch (err) {
    console.warn("Stax: loadChatHistory failed", err);
    return { ok: true, messages: [] };
  }
}

async function appendChatHistory(entries) {
  try {
    const { [CHAT_KEY]: raw = [] } = await chrome.storage.local.get([CHAT_KEY]);
    const stamped = entries.map(e => ({ ...e, at: e.at || Date.now() }));
    // Keep the newest CHAT_MAX_MESSAGES. Trimming from the front means a long
    // session loses its oldest turns rather than refusing to save new ones.
    const merged = [...raw, ...stamped].slice(-CHAT_MAX_MESSAGES);
    await chrome.storage.local.set({ [CHAT_KEY]: merged });
    return { ok: true };
  } catch (err) {
    console.warn("Stax: appendChatHistory failed", err);
    return { ok: false };
  }
}

async function clearChatHistory() {
  try {
    await chrome.storage.local.remove([CHAT_KEY]);
    return { ok: true };
  } catch (err) {
    return { ok: false };
  }
}

chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
  if (msg.type === "LOAD_CHAT") {
    loadChatHistory().then(sendResponse);
    return true;
  }
  if (msg.type === "APPEND_CHAT") {
    appendChatHistory(msg.entries).then(sendResponse);
    return true;
  }
  if (msg.type === "CLEAR_CHAT") {
    clearChatHistory().then(sendResponse);
    return true;
  }
});


// ===== modules/features.js =====

// features.js: read-later archive, time tracking, focus mode,
// markdown export, tab hygiene scoring, message router.

// ---- Read-later archive ----
// The reason tabs pile up is that closing one feels like losing it. Archiving
// closes the tab but keeps the title and URL, so "close" stops being
// destructive and the count actually goes down.
const ARCHIVE_KEY = "stax_archive";
const ARCHIVE_CAP = 500;

async function archiveTabs(tabIds, reason = "manual") {
  const tabs = await chrome.tabs.query({});
  const wanted = tabs.filter(t => tabIds.includes(t.id) && t.url && !/^(chrome|chrome-extension|brave|edge|edge-extension|moz-extension|about|file):/.test(t.url));
  if (!wanted.length) return { ok: false, error: "no-valid-tabs" };

  try {
    const { [ARCHIVE_KEY]: archive = [] } = await chrome.storage.local.get([ARCHIVE_KEY]);
    const existing = new Set(archive.map(a => normalizeUrl(a.url)));

    for (const t of wanted) {
      const key = normalizeUrl(t.url);
      if (existing.has(key)) continue; // already saved, no point storing it twice
      existing.add(key);
      archive.push({ id: `${Date.now()}-${t.id}`, url: t.url, title: t.title || t.url, archivedAt: Date.now(), reason });
    }

    // Oldest entries fall off the end rather than letting this grow forever.
    const trimmed = archive.slice(-ARCHIVE_CAP);
    await chrome.storage.local.set({ [ARCHIVE_KEY]: trimmed });

    // Snapshot into the undo store before closing, same as dedupe, so a
    // mis-click is recoverable for the usual two minutes.
    const records = wanted.map(t => ({ url: t.url, title: t.title || "" }));
    const [activeTab] = await chrome.tabs.query({ active: true, lastFocusedWindow: true });
    await chrome.tabs.remove(wanted.map(t => t.id));
    await recordLastAction({ type: "dedupe", windowId: activeTab?.windowId, removedTabs: records });

    return { ok: true, archived: wanted.length };
  } catch (err) {
    console.warn("Stax: archiveTabs failed", err);
    return { ok: false, error: "storage-failed" };
  }
}

// Archives tabs nothing has touched in a while. Unlike suspend, this closes
// things, so a tab with no recorded activity is SKIPPED rather than assumed
// stale: suspending a tab you misjudged is free, closing one is not.
async function archiveStaleTabs(windowId, days = 7) {
  const thresholdMs = days * 24 * 60 * 60 * 1000;
  const tabs = await chrome.tabs.query({ windowId, pinned: false, active: false, audible: false });
  let tabLastActive = {};
  try {
    ({ tabLastActive = {} } = await chrome.storage.session.get(["tabLastActive"]));
  } catch (err) {
    return { ok: false, error: "no-activity-data" };
  }

  const now = Date.now();
  const stale = tabs.filter(t => {
    const last = tabLastActive[t.id];
    if (!last) return false; // never seen it active, so don't gamble on closing it
    return now - last >= thresholdMs;
  }).map(t => t.id);

  if (!stale.length) return { ok: true, archived: 0 };
  return archiveTabs(stale, `stale-${days}d`);
}

async function listArchive() {
  const { [ARCHIVE_KEY]: archive = [] } = await chrome.storage.local.get([ARCHIVE_KEY]);
  return archive.slice().sort((a, b) => b.archivedAt - a.archivedAt);
}

async function restoreArchived(id, { keep = false } = {}) {
  const { [ARCHIVE_KEY]: archive = [] } = await chrome.storage.local.get([ARCHIVE_KEY]);
  const entry = archive.find(a => a.id === id);
  if (!entry) return { ok: false, error: "not-found" };
  await chrome.tabs.create({ url: entry.url, active: true });
  // Reopening usually means you're done with the saved copy, but keep is
  // there for reference material you want to hold onto.
  if (!keep) await chrome.storage.local.set({ [ARCHIVE_KEY]: archive.filter(a => a.id !== id) });
  return { ok: true };
}

async function deleteArchived(id) {
  const { [ARCHIVE_KEY]: archive = [] } = await chrome.storage.local.get([ARCHIVE_KEY]);
  await chrome.storage.local.set({ [ARCHIVE_KEY]: archive.filter(a => a.id !== id) });
  return { ok: true };
}

async function clearArchive() {
  await chrome.storage.local.set({ [ARCHIVE_KEY]: [] });
  return { ok: true };
}

// ---- Time tracking ----
// Accumulates active-tab time per category per day, entirely locally. The
// "currently being timed" marker lives in storage.session because an MV3
// worker is killed constantly and an in-memory timestamp would vanish with
// it, silently losing every stretch of time between restarts.
const TIME_STATS_KEY = "stax_time_stats";
const TIME_KEEP_DAYS = 21;
const TIME_MIN_SLICE_MS = 3000;   // ignore fly-through tab switches
const TIME_MAX_SLICE_MS = 30 * 60 * 1000; // a slice longer than this means the machine slept

function dayKey(ts = Date.now()) {
  return new Date(ts).toISOString().slice(0, 10);
}

async function flushTimeSlice() {
  try {
    const { staxTimer } = await chrome.storage.session.get(["staxTimer"]);
    if (!staxTimer?.category || !staxTimer.since) return;

    const elapsed = Date.now() - staxTimer.since;
    // Both guards matter: the lower one keeps rapid switching out of the
    // stats, the upper one stops an overnight sleep counting as 9 hours.
    if (elapsed < TIME_MIN_SLICE_MS || elapsed > TIME_MAX_SLICE_MS) return;

    const { [TIME_STATS_KEY]: stats = {} } = await chrome.storage.local.get([TIME_STATS_KEY]);
    const day = dayKey(staxTimer.since);
    stats[day] = stats[day] || {};
    stats[day][staxTimer.category] = (stats[day][staxTimer.category] || 0) + elapsed;

    // Prune old days so this can't grow without bound.
    const cutoff = dayKey(Date.now() - TIME_KEEP_DAYS * 24 * 60 * 60 * 1000);
    Object.keys(stats).forEach(d => { if (d < cutoff) delete stats[d]; });

    await chrome.storage.local.set({ [TIME_STATS_KEY]: stats });
  } catch (err) {
    console.warn("Stax: flushTimeSlice failed", err);
  }
}

async function startTimingTab(tab) {
  await flushTimeSlice();
  if (!tab?.url) return;
  try {
    const rules = await getAllRules();
    const cat = await getCategoryForTab(tab.url, rules, tab.title);
    await chrome.storage.session.set({
      staxTimer: { category: cat?.name || "Uncategorised", since: Date.now() }
    });
  } catch (err) {
    console.warn("Stax: startTimingTab failed", err);
  }
}

chrome.tabs.onActivated.addListener(async ({ tabId }) => {
  try { await startTimingTab(await chrome.tabs.get(tabId)); } catch { /* tab already gone */ }
});
chrome.tabs.onUpdated.addListener(async (tabId, changeInfo, tab) => {
  // A navigation inside the same tab can change its category, so re-time it.
  if (changeInfo.status === "complete" && tab.active) await startTimingTab(tab);
});
chrome.windows.onFocusChanged.addListener(async (windowId) => {
  if (windowId === chrome.windows.WINDOW_ID_NONE) {
    // Browser lost focus: bank what we have rather than counting time spent
    // in another application.
    await flushTimeSlice();
    await chrome.storage.session.remove(["staxTimer"]).catch(() => {});
    return;
  }
  try {
    const [tab] = await chrome.tabs.query({ active: true, windowId });
    if (tab) await startTimingTab(tab);
  } catch { /* window closed */ }
});

async function getTimeStats(days = 7) {
  await flushTimeSlice(); // include the stretch in progress so today looks right
  const { [TIME_STATS_KEY]: stats = {} } = await chrome.storage.local.get([TIME_STATS_KEY]);

  const totals = {};
  const perDay = [];
  for (let i = days - 1; i >= 0; i--) {
    const key = dayKey(Date.now() - i * 24 * 60 * 60 * 1000);
    const day = stats[key] || {};
    let dayTotal = 0;
    Object.entries(day).forEach(([cat, ms]) => {
      totals[cat] = (totals[cat] || 0) + ms;
      dayTotal += ms;
    });
    perDay.push({ day: key, total: dayTotal });
  }

  const ranked = Object.entries(totals)
    .sort((a, b) => b[1] - a[1])
    .map(([category, ms]) => ({ category, ms }));

  return { ok: true, totals: ranked, perDay, grandTotal: ranked.reduce((n, r) => n + r.ms, 0) };
}

async function resetTimeStats() {
  await chrome.storage.local.set({ [TIME_STATS_KEY]: {} });
  await chrome.storage.session.remove(["staxTimer"]).catch(() => {});
  return { ok: true };
}

// ---- Focus mode ----
// Collapses every group except the one holding the active tab, and optionally
// suspends the tabs in those groups too. Stores what it collapsed so exiting
// restores the previous state rather than just expanding everything.
const FOCUS_KEY = "stax_focus";

async function enterFocusMode(windowId, { suspendOthers = false } = {}) {
  const [activeTab] = await chrome.tabs.query({ active: true, windowId });
  if (!activeTab) return { ok: false, error: "no-active-tab" };

  const keepGroupId = activeTab.groupId !== chrome.tabGroups.TAB_GROUP_ID_NONE ? activeTab.groupId : null;
  const groups = await chrome.tabGroups.query({ windowId });

  const previouslyCollapsed = groups.filter(g => g.collapsed).map(g => g.id);
  const toCollapse = groups.filter(g => g.id !== keepGroupId && !g.collapsed);

  for (const g of toCollapse) {
    try { await chrome.tabGroups.update(g.id, { collapsed: true }); } catch { /* group vanished */ }
  }

  let suspended = 0;
  if (suspendOthers) {
    const others = await chrome.tabs.query({ windowId, pinned: false, active: false, audible: false, discarded: false });
    for (const t of others) {
      if (keepGroupId && t.groupId === keepGroupId) continue;
      try { await chrome.tabs.discard(t.id); suspended++; } catch { /* can't discard */ }
    }
  }

  await chrome.storage.session.set({
    [FOCUS_KEY]: { windowId, keepGroupId, previouslyCollapsed, collapsed: toCollapse.map(g => g.id) }
  });
  return { ok: true, collapsed: toCollapse.length, suspended };
}

async function exitFocusMode(windowId) {
  const { [FOCUS_KEY]: state } = await chrome.storage.session.get([FOCUS_KEY]);
  if (!state) return { ok: false, error: "not-in-focus" };

  for (const id of state.collapsed) {
    // Anything the user already had collapsed before focus mode stays that
    // way; only expand what focus mode itself collapsed.
    if (state.previouslyCollapsed.includes(id)) continue;
    try { await chrome.tabGroups.update(id, { collapsed: false }); } catch { /* gone */ }
  }
  await chrome.storage.session.remove([FOCUS_KEY]);
  return { ok: true };
}

async function getFocusState() {
  const { [FOCUS_KEY]: state } = await chrome.storage.session.get([FOCUS_KEY]);
  return { active: !!state, windowId: state?.windowId ?? null };
}

// ---- Markdown export ----
// Built here rather than in the popup so it can see group membership, and
// returned as a string for the popup to put on the clipboard.
async function exportWindowMarkdown(windowId) {
  const tabs = await chrome.tabs.query({ windowId, pinned: false });
  const groups = await chrome.tabGroups.query({ windowId });
  const groupById = new Map(groups.map(g => [g.id, g]));

  const usable = tabs.filter(t => t.url && !/^(chrome|chrome-extension|brave|edge|edge-extension|moz-extension|about|file):/.test(t.url));
  if (!usable.length) return { ok: false, error: "no-tabs" };

  const buckets = new Map();
  for (const t of usable) {
    const g = t.groupId !== chrome.tabGroups.TAB_GROUP_ID_NONE ? groupById.get(t.groupId) : null;
    const key = g?.title || "Ungrouped";
    if (!buckets.has(key)) buckets.set(key, []);
    buckets.get(key).push(t);
  }

  const lines = [`# Tabs, ${new Date().toLocaleDateString()}`, ""];
  // Ungrouped last: the named groups are the part worth reading first.
  const keys = [...buckets.keys()].sort((a, b) =>
    a === "Ungrouped" ? 1 : b === "Ungrouped" ? -1 : a.localeCompare(b));

  for (const key of keys) {
    lines.push(`## ${key}`);
    for (const t of buckets.get(key)) {
      // Escape ] so a bracket in a page title can't break the link syntax.
      const title = (t.title || t.url).replace(/\]/g, "\\]");
      lines.push(`- [${title}](${t.url})`);
    }
    lines.push("");
  }

  return { ok: true, markdown: lines.join("\n"), count: usable.length };
}

// ---- Tab hygiene, for Stacklet's mood ----
async function getTabHygiene(windowId) {
  const tabs = await chrome.tabs.query({ windowId, pinned: false });
  const groups = await chrome.tabGroups.query({ windowId });
  const grouped = tabs.filter(t => t.groupId !== chrome.tabGroups.TAB_GROUP_ID_NONE).length;

  let mood = "happy";
  if (tabs.length >= 60) mood = "buried";
  else if (tabs.length >= 35) mood = "stressed";
  else if (tabs.length >= 15) mood = "neutral";

  return {
    ok: true,
    tabCount: tabs.length,
    groupCount: groups.length,
    groupedRatio: tabs.length ? grouped / tabs.length : 1,
    mood
  };
}

// ---- Message routing for everything added above ----
chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
  if (msg.type === "UNDO_LAST_ACTION") {
    undoLastAction().then(sendResponse);
    return true;
  }
  if (msg.type === "GET_UNDO_STATE") {
    getUndoableAction().then(action => sendResponse({ available: !!action, type: action?.type || null }));
    return true;
  }
  if (msg.type === "TOGGLE_GROUP_COLLAPSE") {
    toggleGroupCollapse(msg.groupId).then(ok => sendResponse({ ok }));
    return true;
  }
  if (msg.type === "RENAME_GROUP") {
    renameGroup(msg.groupId, msg.title).then(ok => sendResponse({ ok }));
    return true;
  }
  if (msg.type === "MOVE_GROUP_TO_NEW_WINDOW") {
    moveGroupToNewWindow(msg.groupId).then(ok => sendResponse({ ok }));
    return true;
  }
  if (msg.type === "JUMP_TO_TAB") {
    jumpToTab(msg.tabId).then(ok => sendResponse({ ok }));
    return true;
  }
  if (msg.type === "SAVE_SESSION") {
    saveSession(msg.windowId, msg.name).then(sendResponse);
    return true;
  }
  if (msg.type === "LIST_SESSIONS") {
    listSessions().then(sessions => sendResponse({ ok: true, sessions }));
    return true;
  }
  if (msg.type === "RESTORE_SESSION") {
    restoreSession(msg.id).then(sendResponse);
    return true;
  }
  if (msg.type === "DELETE_SESSION") {
    deleteSession(msg.id).then(() => sendResponse({ ok: true }));
    return true;
  }
  if (msg.type === "SUSPEND_INACTIVE") {
    suspendInactiveTabs(msg.windowId).then(count => sendResponse({ ok: true, suspended: count }));
    return true;
  }
  if (msg.type === "AI_SEARCH_TABS") {
    aiSearchTabs(msg.windowId, msg.query).then(sendResponse);
    return true;
  }
  if (msg.type === "STACKLET_CHAT") {
    stackletChat(msg.windowId, msg.message, msg.history).then(sendResponse);
    return true;
  }
  if (msg.type === "STACKLET_RUN_ACTION") {
    runStackletAction(msg.action, msg.windowId).then(sendResponse);
    return true;
  }
  if (msg.type === "ARCHIVE_TABS") {
    archiveTabs(msg.tabIds, msg.reason).then(sendResponse);
    return true;
  }
  if (msg.type === "ARCHIVE_STALE") {
    archiveStaleTabs(msg.windowId, msg.days).then(sendResponse);
    return true;
  }
  if (msg.type === "LIST_ARCHIVE") {
    listArchive().then(items => sendResponse({ ok: true, items }));
    return true;
  }
  if (msg.type === "RESTORE_ARCHIVED") {
    restoreArchived(msg.id, { keep: msg.keep }).then(sendResponse);
    return true;
  }
  if (msg.type === "DELETE_ARCHIVED") {
    deleteArchived(msg.id).then(sendResponse);
    return true;
  }
  if (msg.type === "CLEAR_ARCHIVE") {
    clearArchive().then(sendResponse);
    return true;
  }
  if (msg.type === "GET_TIME_STATS") {
    getTimeStats(msg.days).then(sendResponse);
    return true;
  }
  if (msg.type === "RESET_TIME_STATS") {
    resetTimeStats().then(sendResponse);
    return true;
  }
  if (msg.type === "ENTER_FOCUS") {
    enterFocusMode(msg.windowId, { suspendOthers: msg.suspendOthers }).then(sendResponse);
    return true;
  }
  if (msg.type === "EXIT_FOCUS") {
    exitFocusMode(msg.windowId).then(sendResponse);
    return true;
  }
  if (msg.type === "GET_FOCUS_STATE") {
    getFocusState().then(sendResponse);
    return true;
  }
  if (msg.type === "EXPORT_MARKDOWN") {
    exportWindowMarkdown(msg.windowId).then(sendResponse);
    return true;
  }
  if (msg.type === "GET_HYGIENE") {
    getTabHygiene(msg.windowId).then(sendResponse);
    return true;
  }
  if (msg.type === "GET_ACCESSORIES") {
    getAccessories().then(sendResponse);
    return true;
  }
  if (msg.type === "EQUIP_ACCESSORY") {
    equipAccessory(msg.id).then(sendResponse);
    return true;
  }
  // Bump usage counters when core actions complete so accessories unlock
  // at the right time without the popup having to know about them.
  if (msg.type === "BUMP_USAGE") {
    bumpUsage(msg.key, msg.by || 1).then(r => sendResponse({ ok: true, newItems: r }));
    return true;
  }
  if (msg.type === "GET_RECENTLY_CLOSED") {
    getRecentlyClosed().then(tabs => sendResponse({ ok: true, tabs }));
    return true;
  }
  if (msg.type === "RESTORE_RECENTLY_CLOSED") {
    restoreRecentlyClosed(msg.sessionId).then(sendResponse);
    return true;
  }
  if (msg.type === "MERGE_WINDOWS") {
    mergeAllWindows().then(sendResponse);
    return true;
  }
  if (msg.type === "SPLIT_WINDOWS") {
    splitIntoWindows(msg.windowId).then(sendResponse);
    return true;
  }
  if (msg.type === "CLOSE_GROUP_TABS") {
    closeGroupTabs(msg.groupId).then(sendResponse);
    return true;
  }
  if (msg.type === "MOVE_GROUP_BY") {
    moveGroupBy(msg.groupId, msg.direction).then(sendResponse);
    return true;
  }
  if (msg.type === "GET_TAB_TREE") {
    getTabTree(msg.windowId).then(sendResponse);
    return true;
  }
  if (msg.type === "GET_WEEKLY_DIGEST") {
    getWeeklyDigest().then(sendResponse);
    return true;
  }
  if (msg.type === "GET_SUGGESTED_RULES") {
    getSuggestedRules().then(sendResponse);
    return true;
  }
  if (msg.type === "ACCEPT_SUGGESTED_RULE") {
    acceptSuggestedRule(msg.domains, msg.name, msg.color).then(sendResponse);
    return true;
  }
  if (msg.type === "DISMISS_SUGGESTED_RULE") {
    dismissSuggestedRule(msg.domains).then(sendResponse);
    return true;
  }
  if (msg.type === "SNOOZE_TABS") {
    snoozeTabs(msg.tabIds, msg.preset, msg.customTime).then(sendResponse);
    return true;
  }
  if (msg.type === "LIST_SNOOZED") {
    listSnoozed().then(items => sendResponse({ ok: true, items }));
    return true;
  }
  if (msg.type === "CANCEL_SNOOZE") {
    cancelSnooze(msg.id, msg.reopenNow).then(sendResponse);
    return true;
  }
});

// ---- Points, levels, and accessories ----
// Every meaningful interaction earns points, and accessories unlock at point
// thresholds. This replaced a set of separate counters (sorts, dedupes,
// sessions) each gating its own item: that meant someone who used one feature
// heavily never unlocked anything, while the point pool rewards any use.
// Points are awarded per action type, weighted by effort rather than
// frequency, so spamming the cheapest button isn't the fastest route.
const ACC_KEY = "stax_accessories";
const USAGE_KEY = "stax_usage";

const POINT_VALUES = {
  sort: 10,          // the core action
  ai_sort: 15,       // costs the user an API call, worth more
  dedupe: 8,
  suspend: 6,
  focus: 5,
  session_save: 12,
  session_restore: 6,
  archive: 8,
  merge: 6,
  split: 6,
  export: 4,
  chat: 5,           // talking to Stacklet
  action_run: 10,    // approving one of his suggestions
  poke: 1,           // capped in practice by the cooldown below
  tutorial: 25,      // one-off, rewards finishing onboarding
};

// Levels are just labelled point bands. Kept generous early so the first
// unlock lands in the first session, then widening so later ones feel earned.
const LEVEL_THRESHOLDS = [0, 25, 75, 150, 275, 450, 700, 1000, 1400];

function levelFor(points) {
  let lvl = 1;
  for (let i = 0; i < LEVEL_THRESHOLDS.length; i++) {
    if (points >= LEVEL_THRESHOLDS[i]) lvl = i + 1;
  }
  return lvl;
}

function pointsForNextLevel(points) {
  const next = LEVEL_THRESHOLDS.find(t => t > points);
  return next == null ? null : next;
}

const ACCESSORY_DEFS = [
  { id: "hat",        label: "Tiny Hat",   cost: 25 },
  { id: "glasses",    label: "Glasses",    cost: 75 },
  { id: "scarf",      label: "Scarf",      cost: 150 },
  { id: "headphones", label: "Headphones", cost: 275 },
  { id: "backpack",   label: "Backpack",   cost: 450 },
  { id: "crown",      label: "Crown",      cost: 700 },
  { id: "stars",      label: "Star Aura",  cost: 1000 },
  { id: "cape",       label: "Cape",       cost: 1400 },
];

async function getUsage() {
  const { [USAGE_KEY]: u } = await chrome.storage.sync.get([USAGE_KEY]);
  return u || { points: 0, actions: 0, firstSeen: Date.now(), lastPoke: 0 };
}

// Awards points and returns anything newly unlocked, so the UI can show a
// toast in the same interaction rather than on next open.
async function awardPoints(kind, multiplier = 1) {
  try {
    const u = await getUsage();
    const base = POINT_VALUES[kind] ?? 0;
    if (!base) return { ok: true, gained: 0, newItems: [], usage: u };

    // Poking is free entertainment, so it only pays out once a minute.
    // Without this, holding down a click would farm every accessory.
    if (kind === "poke") {
      if (Date.now() - (u.lastPoke || 0) < 60000) {
        return { ok: true, gained: 0, newItems: [], usage: u };
      }
      u.lastPoke = Date.now();
    }

    const before = u.points || 0;
    const gained = Math.round(base * multiplier);
    u.points = before + gained;
    u.actions = (u.actions || 0) + 1;

    const newItems = ACCESSORY_DEFS.filter(d => d.cost > before && d.cost <= u.points);
    if (newItems.length) {
      const { [ACC_KEY]: owned = [] } = await chrome.storage.sync.get([ACC_KEY]);
      const ownedIds = new Set(owned.map(a => a.id));
      const toAdd = newItems.filter(d => !ownedIds.has(d.id));
      if (toAdd.length) {
        await chrome.storage.sync.set({
          [ACC_KEY]: [...owned, ...toAdd.map(d => ({ id: d.id, unlockedAt: Date.now() }))]
        });
      }
    }

    await chrome.storage.sync.set({ [USAGE_KEY]: u });
    return {
      ok: true,
      gained,
      points: u.points,
      level: levelFor(u.points),
      levelUp: levelFor(before) !== levelFor(u.points),
      newItems,
    };
  } catch (err) {
    console.warn("Stax: awardPoints failed", err);
    return { ok: false, gained: 0, newItems: [] };
  }
}

async function getAccessories() {
  const u = await getUsage();
  const { [ACC_KEY]: owned = [] } = await chrome.storage.sync.get([ACC_KEY]);
  const { stackletAccessory = null } = await chrome.storage.sync.get(["stackletAccessory"]);
  const ownedIds = new Set(owned.map(a => a.id));
  const points = u.points || 0;
  const nextAt = pointsForNextLevel(points);

  return {
    ok: true,
    points,
    level: levelFor(points),
    nextLevelAt: nextAt,
    progressToNext: nextAt ? Math.round(((points - (LEVEL_THRESHOLDS[levelFor(points) - 1] || 0)) / (nextAt - (LEVEL_THRESHOLDS[levelFor(points) - 1] || 0))) * 100) : 100,
    equipped: stackletAccessory,
    all: ACCESSORY_DEFS.map(d => ({
      id: d.id,
      label: d.label,
      cost: d.cost,
      unlocked: ownedIds.has(d.id) || points >= d.cost,
      remaining: Math.max(0, d.cost - points),
    })),
  };
}

async function equipAccessory(id) {
  if (id) {
    const acc = await getAccessories();
    const item = acc.all.find(a => a.id === id);
    if (!item?.unlocked) return { ok: false, error: "not-unlocked" };
  }
  await chrome.storage.sync.set({ stackletAccessory: id || null });
  return { ok: true };
}


// ---- Weekly digest ----
// Rolls the stats already being collected into a readable summary. Generated
// on demand rather than stored, so there's no second source of truth to keep
// in sync with the raw per-day data.
async function getWeeklyDigest() {
  try {
    const stats = await getTimeStats(7);
    const usage = await getUsage();
    const { [ARCHIVE_KEY]: archive = [] } = await chrome.storage.local.get([ARCHIVE_KEY]);
    const { [SESSIONS_KEY]: sessions = [] } = await chrome.storage.local.get([SESSIONS_KEY]);

    const weekAgo = Date.now() - 7 * 86400000;
    const archivedThisWeek = archive.filter(a => a.archivedAt >= weekAgo).length;
    const sessionsThisWeek = sessions.filter(s => s.savedAt >= weekAgo).length;

    const busiest = (stats.perDay || []).reduce(
      (best, d) => (d.total > (best?.total ?? -1) ? d : best), null);
    const topCategory = (stats.totals || [])[0] || null;

    // Compare the back half of the week against the front half. Anything
    // shorter than a full week of data makes the trend meaningless, so it's
    // reported as null rather than a misleading number.
    const days = stats.perDay || [];
    let trend = null;
    if (days.length >= 6 && stats.grandTotal > 0) {
      const half = Math.floor(days.length / 2);
      const early = days.slice(0, half).reduce((a, d) => a + d.total, 0);
      const late = days.slice(half).reduce((a, d) => a + d.total, 0);
      if (early > 0) trend = Math.round(((late - early) / early) * 100);
    }

    return {
      ok: true,
      totalMs: stats.grandTotal || 0,
      perDay: days,
      categories: (stats.totals || []).slice(0, 5),
      busiestDay: busiest?.day || null,
      busiestMs: busiest?.total || 0,
      topCategory: topCategory?.category || null,
      archivedThisWeek,
      sessionsThisWeek,
      points: usage.points || 0,
      level: levelFor(usage.points || 0),
      trend,
    };
  } catch (err) {
    console.warn("Stax: getWeeklyDigest failed", err);
    return { ok: false, error: err.message };
  }
}

// ---- Rules learned from behaviour ----
// When the user manually drops two domains into the same group repeatedly,
// that's a rule they're enacting by hand. This watches for the pattern and
// offers to make it permanent, rather than requiring them to discover the
// custom-rules editor.
const COOCCUR_KEY = "stax_cooccurrence";
const SUGGEST_THRESHOLD = 3;

async function recordManualGrouping(groupId) {
  try {
    const tabs = await chrome.tabs.query({ groupId });
    const group = await chrome.tabGroups.get(groupId);
    const hosts = [...new Set(tabs.map(t => {
      try { return new URL(t.url).hostname.replace(/^www\./, ""); } catch { return null; }
    }).filter(Boolean))];
    if (hosts.length < 2) return;

    const { [COOCCUR_KEY]: data = {} } = await chrome.storage.local.get([COOCCUR_KEY]);

    // Key on the sorted host pair so a,b and b,a are the same observation.
    for (let i = 0; i < hosts.length; i++) {
      for (let j = i + 1; j < hosts.length; j++) {
        const key = [hosts[i], hosts[j]].sort().join("|");
        const entry = data[key] || { count: 0, names: {} };
        entry.count++;
        if (group.title) entry.names[group.title] = (entry.names[group.title] || 0) + 1;
        data[key] = entry;
      }
    }
    await chrome.storage.local.set({ [COOCCUR_KEY]: data });
  } catch (err) {
    console.warn("Stax: recordManualGrouping failed", err);
  }
}

// Returns pairs seen together often enough to be worth a rule, excluding
// anything an existing rule already covers.
async function getSuggestedRules() {
  try {
    const { [COOCCUR_KEY]: data = {} } = await chrome.storage.local.get([COOCCUR_KEY]);
    const { customRules = [] } = await chrome.storage.sync.get(["customRules"]);
    const covered = new Set(customRules.flatMap(r => r.domains || []));

    const suggestions = Object.entries(data)
      .filter(([, v]) => v.count >= SUGGEST_THRESHOLD)
      .map(([key, v]) => {
        const domains = key.split("|");
        // Use the group name they picked most often for this pair.
        const name = Object.entries(v.names).sort((a, b) => b[1] - a[1])[0]?.[0] || domains[0];
        return { domains, name, count: v.count };
      })
      .filter(s => !s.domains.every(d => covered.has(d)))
      .sort((a, b) => b.count - a.count)
      .slice(0, 5);

    return { ok: true, suggestions };
  } catch (err) {
    return { ok: false, suggestions: [] };
  }
}

async function acceptSuggestedRule(domains, name, color = "cyan") {
  try {
    const { customRules = [] } = await chrome.storage.sync.get(["customRules"]);
    customRules.push({ name, domains, color });
    await chrome.storage.sync.set({ customRules });
    // Forget the observation so it can't be suggested twice.
    const { [COOCCUR_KEY]: data = {} } = await chrome.storage.local.get([COOCCUR_KEY]);
    delete data[[...domains].sort().join("|")];
    await chrome.storage.local.set({ [COOCCUR_KEY]: data });
    return { ok: true };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

async function dismissSuggestedRule(domains) {
  try {
    const { [COOCCUR_KEY]: data = {} } = await chrome.storage.local.get([COOCCUR_KEY]);
    delete data[[...domains].sort().join("|")];
    await chrome.storage.local.set({ [COOCCUR_KEY]: data });
    return { ok: true };
  } catch (err) {
    return { ok: false };
  }
}

// A group the user created or renamed by hand is the signal we learn from.
// Stax-created groups are excluded: learning from our own output would
// reinforce whatever the classifier already does.
chrome.tabGroups.onUpdated.addListener(async (group) => {
  try {
    const { stax_recent_auto = [] } = await chrome.storage.session.get(["stax_recent_auto"]);
    if (stax_recent_auto.includes(group.id)) return;
    if (group.title) recordManualGrouping(group.id);
  } catch { /* best effort */ }
});

// ---- Message routing ----
chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
  if (msg.type === "UNDO_LAST_ACTION") {
    undoLastAction().then(sendResponse);
    return true;
  }
  if (msg.type === "GET_UNDO_STATE") {
    getUndoableAction().then(action => sendResponse({ available: !!action, type: action?.type || null }));
    return true;
  }
  if (msg.type === "ARCHIVE_TABS") {
    archiveTabs(msg.tabIds).then(sendResponse);
    return true;
  }
  if (msg.type === "ARCHIVE_STALE") {
    archiveStaleTabs(msg.windowId, msg.days).then(sendResponse);
    return true;
  }
  if (msg.type === "LIST_ARCHIVE") {
    listArchive().then(sendResponse);
    return true;
  }
  if (msg.type === "RESTORE_ARCHIVED") {
    restoreArchived(msg.id, msg.keep).then(sendResponse);
    return true;
  }
  if (msg.type === "DELETE_ARCHIVED") {
    deleteArchived(msg.id).then(sendResponse);
    return true;
  }
  if (msg.type === "CLEAR_ARCHIVE") {
    clearArchive().then(sendResponse);
    return true;
  }
  if (msg.type === "GET_TIME_STATS") {
    getTimeStats(msg.days).then(sendResponse);
    return true;
  }
  if (msg.type === "RESET_TIME_STATS") {
    resetTimeStats().then(sendResponse);
    return true;
  }
  if (msg.type === "ENTER_FOCUS") {
    enterFocusMode(msg.windowId, { suspendOthers: msg.suspendOthers }).then(sendResponse);
    return true;
  }
  if (msg.type === "EXIT_FOCUS") {
    exitFocusMode(msg.windowId).then(sendResponse);
    return true;
  }
  if (msg.type === "GET_FOCUS_STATE") {
    getFocusState().then(sendResponse);
    return true;
  }
  if (msg.type === "EXPORT_MARKDOWN") {
    exportWindowMarkdown(msg.windowId).then(sendResponse);
    return true;
  }
  if (msg.type === "GET_HYGIENE") {
    getTabHygiene(msg.windowId).then(sendResponse);
    return true;
  }
  if (msg.type === "GET_ACCESSORIES") {
    getAccessories().then(sendResponse);
    return true;
  }
  if (msg.type === "EQUIP_ACCESSORY") {
    equipAccessory(msg.id).then(sendResponse);
    return true;
  }
  if (msg.type === "AWARD_POINTS") {
    awardPoints(msg.kind, msg.multiplier).then(sendResponse);
    return true;
  }
  if (msg.type === "GET_RECENTLY_CLOSED") {
    getRecentlyClosed().then(tabs => sendResponse({ ok: true, tabs }));
    return true;
  }
  if (msg.type === "RESTORE_RECENTLY_CLOSED") {
    restoreRecentlyClosed(msg.sessionId).then(sendResponse);
    return true;
  }
  if (msg.type === "MERGE_WINDOWS") {
    mergeAllWindows().then(sendResponse);
    return true;
  }
  if (msg.type === "SPLIT_WINDOWS") {
    splitIntoWindows(msg.windowId).then(sendResponse);
    return true;
  }
  if (msg.type === "CLOSE_GROUP_TABS") {
    closeGroupTabs(msg.groupId).then(sendResponse);
    return true;
  }
  if (msg.type === "MOVE_GROUP_BY") {
    moveGroupBy(msg.groupId, msg.direction).then(sendResponse);
    return true;
  }
  if (msg.type === "GET_TAB_TREE") {
    getTabTree(msg.windowId).then(sendResponse);
    return true;
  }
  if (msg.type === "GET_WEEKLY_DIGEST") {
    getWeeklyDigest().then(sendResponse);
    return true;
  }
  if (msg.type === "GET_SUGGESTED_RULES") {
    getSuggestedRules().then(sendResponse);
    return true;
  }
  if (msg.type === "ACCEPT_SUGGESTED_RULE") {
    acceptSuggestedRule(msg.domains, msg.name, msg.color).then(sendResponse);
    return true;
  }
  if (msg.type === "DISMISS_SUGGESTED_RULE") {
    dismissSuggestedRule(msg.domains).then(sendResponse);
    return true;
  }
  if (msg.type === "SNOOZE_TABS") {
    snoozeTabs(msg.tabIds, msg.preset, msg.customTime).then(sendResponse);
    return true;
  }
  if (msg.type === "LIST_SNOOZED") {
    listSnoozed().then(items => sendResponse({ ok: true, items }));
    return true;
  }
  if (msg.type === "CANCEL_SNOOZE") {
    cancelSnooze(msg.id, msg.reopenNow).then(sendResponse);
    return true;
  }
});

// ---- Snooze ----
// Close a tab now, reopen it at a chosen time. Stored in storage.local so it
// survives a browser restart, and backed by chrome.alarms rather than a
// setTimeout: a service worker gets killed constantly in MV3, and a timeout
// would die with it. Alarms are re-delivered by the browser even after a
// restart, which is exactly the lifetime this needs.
const SNOOZE_KEY = "stax_snoozed";
const SNOOZE_ALARM_PREFIX = "stax_snooze_";

// Fixed presets keep the UI to one tap. "Later today" and the morning
// options resolve against the user's actual clock, not a fixed offset, so
// "tomorrow morning" means 9am tomorrow rather than 24 hours from now.
function resolveSnoozeTime(preset) {
  const now = new Date();
  const at = new Date(now);

  switch (preset) {
    case "1h":
      at.setHours(at.getHours() + 1);
      break;
    case "3h":
      at.setHours(at.getHours() + 3);
      break;
    case "tonight":
      at.setHours(19, 0, 0, 0);
      // Already past 7pm, so push to tomorrow rather than firing instantly.
      if (at <= now) at.setDate(at.getDate() + 1);
      break;
    case "tomorrow":
      at.setDate(at.getDate() + 1);
      at.setHours(9, 0, 0, 0);
      break;
    case "weekend": {
      // Next Saturday at 10am. If it's already the weekend, this means the
      // coming Saturday, not today.
      const day = at.getDay();
      const daysUntilSat = (6 - day + 7) % 7 || 7;
      at.setDate(at.getDate() + daysUntilSat);
      at.setHours(10, 0, 0, 0);
      break;
    }
    case "nextweek": {
      const day = at.getDay();
      const daysUntilMon = (1 - day + 7) % 7 || 7;
      at.setDate(at.getDate() + daysUntilMon);
      at.setHours(9, 0, 0, 0);
      break;
    }
    default:
      return null;
  }
  return at.getTime();
}

async function snoozeTabs(tabIds, preset, customTime = null) {
  const wakeAt = customTime || resolveSnoozeTime(preset);
  if (!wakeAt || wakeAt <= Date.now()) return { ok: false, error: "bad-time" };

  try {
    const tabs = await chrome.tabs.query({ currentWindow: true });
    const targets = tabs.filter(t => tabIds.includes(t.id) && t.url &&
      !/^(chrome|chrome-extension|brave|edge|edge-extension|moz-extension|about|file):/.test(t.url));
    if (!targets.length) return { ok: false, error: "no-valid-tabs" };

    const { [SNOOZE_KEY]: snoozed = [] } = await chrome.storage.local.get([SNOOZE_KEY]);
    const created = [];

    for (const tab of targets) {
      const id = `${Date.now()}_${tab.id}`;
      const entry = {
        id,
        url: tab.url,
        title: tab.title || "",
        wakeAt,
        snoozedAt: Date.now(),
        windowId: tab.windowId,
      };
      snoozed.push(entry);
      created.push(entry);
      // One alarm per tab. Chrome caps alarm frequency but not count, and
      // per-tab alarms mean cancelling one doesn't disturb the others.
      await chrome.alarms.create(SNOOZE_ALARM_PREFIX + id, { when: wakeAt });
    }

    await chrome.storage.local.set({ [SNOOZE_KEY]: snoozed });

    // Snapshot for undo before the tabs disappear.
    await recordLastAction({
      type: "dedupe",
      windowId: targets[0].windowId,
      removedTabs: targets.map(t => ({ url: t.url, title: t.title || "" })),
    });
    await chrome.tabs.remove(targets.map(t => t.id));

    return { ok: true, count: created.length, wakeAt };
  } catch (err) {
    console.warn("Stax: snoozeTabs failed", err);
    return { ok: false, error: err.message };
  }
}

async function listSnoozed() {
  const { [SNOOZE_KEY]: snoozed = [] } = await chrome.storage.local.get([SNOOZE_KEY]);
  return snoozed.slice().sort((a, b) => a.wakeAt - b.wakeAt);
}

async function cancelSnooze(id, reopenNow = false) {
  try {
    const { [SNOOZE_KEY]: snoozed = [] } = await chrome.storage.local.get([SNOOZE_KEY]);
    const entry = snoozed.find(s => s.id === id);
    if (!entry) return { ok: false, error: "not-found" };

    await chrome.alarms.clear(SNOOZE_ALARM_PREFIX + id);
    await chrome.storage.local.set({ [SNOOZE_KEY]: snoozed.filter(s => s.id !== id) });
    if (reopenNow) await chrome.tabs.create({ url: entry.url, active: false });
    return { ok: true };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

// Reopens a snoozed tab when its alarm fires. Opens in the background so a
// tab waking up mid-task doesn't steal focus, and badges the toolbar so it
// isn't silent.
async function wakeSnoozed(id) {
  try {
    const { [SNOOZE_KEY]: snoozed = [] } = await chrome.storage.local.get([SNOOZE_KEY]);
    const entry = snoozed.find(s => s.id === id);
    if (!entry) return;

    await chrome.storage.local.set({ [SNOOZE_KEY]: snoozed.filter(s => s.id !== id) });

    // Prefer the window it came from, but fall back to any normal window if
    // that one has since been closed.
    let windowId = entry.windowId;
    try {
      await chrome.windows.get(windowId);
    } catch {
      const wins = await chrome.windows.getAll({ windowTypes: ["normal"] });
      windowId = wins[0]?.id;
    }

    if (windowId != null) await chrome.tabs.create({ windowId, url: entry.url, active: false });
    else await chrome.windows.create({ url: entry.url });

    try {
      await chrome.action.setBadgeText({ text: "!" });
      await chrome.action.setBadgeBackgroundColor({ color: "#c9a7f5" });
      setTimeout(() => refreshBadgeForFocusedWindow(), 5000);
    } catch { /* badge is cosmetic */ }
  } catch (err) {
    console.warn("Stax: wakeSnoozed failed", err);
  }
}

chrome.alarms.onAlarm.addListener((alarm) => {
  if (!alarm.name.startsWith(SNOOZE_ALARM_PREFIX)) return;
  wakeSnoozed(alarm.name.slice(SNOOZE_ALARM_PREFIX.length));
});

// Alarms can be lost if the browser was closed when one was due. On startup,
// reopen anything already past its wake time and re-register the rest.
async function reconcileSnoozeAlarms() {
  try {
    const { [SNOOZE_KEY]: snoozed = [] } = await chrome.storage.local.get([SNOOZE_KEY]);
    if (!snoozed.length) return;
    const now = Date.now();
    const overdue = snoozed.filter(s => s.wakeAt <= now);
    for (const s of overdue) await wakeSnoozed(s.id);
    for (const s of snoozed.filter(s => s.wakeAt > now)) {
      await chrome.alarms.create(SNOOZE_ALARM_PREFIX + s.id, { when: s.wakeAt });
    }
  } catch (err) {
    console.warn("Stax: reconcileSnoozeAlarms failed", err);
  }
}

chrome.runtime.onStartup.addListener(reconcileSnoozeAlarms);
chrome.runtime.onInstalled.addListener(reconcileSnoozeAlarms);